 FIELDS='objectid,plot_code,plot_no,lu_desc,extn_sqyrd,area_sqm,rd_width_m,township,colony,block,district,mandal,village,lpsvillage,rs_no,zoning,latitude,longitude';
const paths={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-8h6v8',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16',legal:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6ZM8 12l3 3 5-6',crda:'M4 7h16M4 12h16M4 17h16M8 4v16M16 4v16',saved:'M6 3h12v18l-6-4-6 4Z',plus:'M12 4v16M4 12h16',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',back:'M15 5l-7 7 7 7',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',share:'M8 12l8-6M8 12l8 6M8 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0M22 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0M22 19a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.home}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=v=>String(v??'').trim().slice(0,250), num=v=>v===''||v===null||v===undefined?null:Number.isFinite(Number(v))?Number(v):null;
const money=n=>!Number(n)?'Price not supplied':Number(n)>=1e7?'₹'+(n/1e7).toFixed(2).replace(/0+$/,'').replace(/\.$/,'')+' Cr':Number(n)>=1e5?'₹'+(n/1e5).toFixed(2).replace(/0+$/,'').replace(/\.$/,'')+' Lakh':'₹'+Number(n).toLocaleString('en-IN');
const fmt=n=>n===null||n===undefined||n===''?'Not supplied':Number.isFinite(Number(n))?Number(n).toLocaleString('en-IN',{maximumFractionDigits:2}):esc(n);
const hash=s=>{let h=0;for(const c of s)h=(Math.imul(31,h)+c.charCodeAt(0))|0;return (h>>>0).toString(36)};
const uid=prefix=>prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const coords=(lat,lon)=>num(lat)!==null&&num(lon)!==null&&Math.abs(+lat)<=85&&Math.abs(+lon)<=180&&!(+lat===0&&+lon===0);
const canonical=s=>clean(s).toUpperCase().replace(/\s/g,'');
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('toast').style.display='none',4200)}
const DEMOS=[
 {id:'d1',title:'Residential plot near Tulluru',type:'Plot',purpose:'Sale',price:4800000,area:240,unit:'sq yd',village:'Tulluru',city:'Amaravati',district:'Guntur',mandal:'Thullur',facing:'East',road:12,lat:16.526,lon:80.468,survey:'DEMO-SURVEY-01',description:'Illustrative residential listing. Add your own property and contact details to use the listing flow.',demo:true,status:'Available'},
 {id:'d2',title:'Family apartment in Mangalagiri',type:'Apartment',purpose:'Sale',price:6800000,area:1450,unit:'sq ft',village:'Mangalagiri',city:'Mangalagiri',district:'Guntur',mandal:'Mangalagiri',facing:'North',bhk:3,road:10,lat:16.440,lon:80.564,description:'Fictional 3-bedroom apartment used to demonstrate property facts and map navigation.',demo:true,status:'Available'},
 {id:'d3',title:'Commercial space in Vijayawada',type:'Commercial',purpose:'Rent',price:35000,area:900,unit:'sq ft',village:'Benz Circle',city:'Vijayawada',district:'NTR',mandal:'Vijayawada',lat:16.500,lon:80.653,description:'Illustrative monthly rental. No genuine availability or contact is represented.',demo:true,status:'Available'},
 {id:'d4',title:'Independent house in Guntur',type:'House',purpose:'Sale',price:9500000,area:2200,unit:'sq ft',village:'Guntur',city:'Guntur',district:'Guntur',mandal:'Guntur',bhk:3,facing:'West',lat:16.306,lon:80.438,description:'Fictional independent house for exploring the detail and legal checklist screens.',demo:true,status:'Available'}
];
let state,lastGood,route='home',args={},stack=[],view={q:'',type:'All',purpose:'All',mine:false,max:''},preview=null,sync={code:'',village:'',offset:0,done:false,busy:false,loaded:0},photoDraft='',editorRef=null,editorCopy=null;
try{state=JSON.parse(localStorage.getItem(KEY)||'null')}catch(e){};
if(!state||state.schema!==2)state={schema:2,listings:DEMOS,refs:[],saved:[],checks:{},notes:{},imports:[],lang:'en'};
lastGood=JSON.stringify(state);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));lastGood=JSON.stringify(state);return true}catch(e){state=JSON.parse(lastGood);toast('Device storage is full. Remove a photo or export your data before retrying.');return false}}
function normalize(f,source='File import',date=new Date().toISOString()){
 const a=f.attributes||f.properties||f, get=(...keys)=>{for(const k of keys){let v=a[k];if(v===undefined){const key=Object.keys(a).find(x=>x.toLowerCase()===k.toLowerCase());v=a[key]}if(v!==undefined&&v!==null&&v!=='')return v}return ''};
 const code=canonical(get('plot_code','plotCode','plot code'));if(!code||!/^\d{1,3}-\d{1,4}-\d{1,5}-\d{1,5}-[A-Z0-9]{1,8}$/.test(code))throw Error('Missing or invalid CRDA plot code');
 let rings=[];if(f.geometry?.rings)rings=f.geometry.rings;else if(f.geometry?.type==='Polygon')rings=f.geometry.coordinates;else if(f.geometry?.type==='MultiPolygon')rings=f.geometry.coordinates.flat();
 rings=rings.slice(0,30).map(r=>r.slice(0,2000).map(p=>[Number(p[0]),Number(p[1])])).filter(r=>r.length>=4&&r.every(p=>coords(p[1],p[0])));
 let lat=num(get('latitude','lat')),lon=num(get('longitude','lon','lng'));
 if(!coords(lat,lon)&&rings.length){const r=rings[0].slice(0,-1);lon=r.reduce((s,p)=>s+p[0],0)/r.length;lat=r.reduce((s,p)=>s+p[1],0)/r.length}
 if(!coords(lat,lon)){lat=null;lon=null}
 let area=num(get('extn_sqyrd','area_sqyd','areaSqYd')),sqm=num(get('area_sqm','areaSqm'));
 if(area!==null&&area<=0)area=null;if(sqm!==null&&sqm<=0)sqm=null;if(area===null&&sqm!==null)area=sqm/0.83612736;
 return {id:'r'+hash(code),code,plotNo:clean(get('plot_no','plotNo')),area,areaSqm:sqm,village:clean(get('lpsvillage','village')),district:clean(get('district')),mandal:clean(get('mandal')),survey:clean(get('rs_no','survey')),landUse:clean(get('lu_desc','landUse')),zoning:clean(get('zoning')),road:num(get('rd_width_m','roadWidthM')),township:clean(get('township')),colony:clean(get('colony')),block:clean(get('block')),lat,lon,rings,source,importedAt:date};
}
if(!state.seeded&&window.CRDA_SNAPSHOT){for(const f of CRDA_SNAPSHOT.features){try{state.refs.push(normalize(f,'CRDA GIS snapshot',CRDA_SNAPSHOT.fetchedAt))}catch(e){}}state.seeded=true;persist()}
function t(en,te){return state.lang==='te'?te:en}
function header(){ $('header').innerHTML=`<div class="mark">${icon('home')}</div><div class="brand"><strong>Agent Mart</strong><small>PROPERTY • AMARAVATI & BEYOND</small></div><button class="iconbtn" aria-label="Change language" onclick="toggleLang()">${state.lang==='en'?'తె':'EN'}</button><button class="iconbtn" aria-label="Add property" onclick="go('edit')">${icon('plus')}</button>`;
 const active=['detail','edit'].includes(route)?'home':route==='ref'?'crda':route;
 $('nav').innerHTML=[['home','Properties','ప్రాపర్టీలు'],['map','Map','మ్యాప్'],['legal','Legal search','లీగల్ సెర్చ్'],['crda','CRDA plots','CRDA ప్లాట్లు'],['saved','Saved','సేవ్ చేసినవి']].map(([id,en,te])=>`<button class="${active===id?'active':''}" onclick="go('${id}')" aria-label="${en}">${icon(id)}<span>${t(en,te)}</span></button>`).join('')}
function toggleLang(){state.lang=state.lang==='en'?'te':'en';persist();render()}
function go(r,a={}){stack.push({route,args,scroll:window.scrollY});route=r;args=a;render();window.scrollTo(0,0)}
function back(){const prev=stack.pop();if(prev){route=prev.route;args=prev.args;render();window.scrollTo(0,prev.scroll);return true}if(route!=='home'){route='home';args={};render();return true}return false}window.androidBack=back;
const backbtn=()=>`<button class="back" onclick="back()">${icon('back')} ${t('Back','వెనుకకు')}</button>`;
function render(){header();try{({home:home,detail:detail,edit:edit,map:mapPage,legal:legal,crda:crda,ref:refDetail,saved:savedPage,preview:previewPage,about:aboutPage}[route]||home)()}catch(e){$('app').innerHTML=`<div class="empty"><h2>Unable to open this view</h2><p>Your saved data is retained.</p><button class="btn" onclick="go('home')">Properties</button></div>`;console.error(e)}}
function illustration(p){return `<svg viewBox="0 0 400 150" aria-label="Property illustration"><rect width="400" height="150" fill="#dfe9e7"/><path d="M0 133 400 68V150H0" fill="#c2d8cb"/><path d="m0 104 400-52M35 150 207 0M200 150 370 0" stroke="#f7faf8" stroke-width="13"/>${p.type==='Plot'?'<path d="m142 65 92-18 63 49-97 20Z" fill="#e8bc7e" stroke="#b28042" stroke-width="3"/><path d="m148 67 88-17 56 45-92 18Z" fill="none" stroke="#fff6" stroke-dasharray="5 4"/>':'<path d="m148 110 0-66 70-17 55 24v68l-55 17Z" fill="#f5f0e6"/><path d="m218 27 55 24v68l-55 17Z" fill="#c5d7dc"/><path d="m141 45 78-25 61 28-9 8-53-20-68 18Z" fill="#517586"/><path d="M164 62v17h17V58ZM192 54v17h16V50ZM235 61v18l17 6V67Z" fill="#87abb5"/>'}</svg>`}
function card(p){return `<article class="card"><div class="visual" onclick="go('detail',{id:'${p.id}'})">${p.photo?`<img src="${p.photo}" alt="Property photo">`:illustration(p)}<span class="tag ${p.demo?'amber':''}">${p.demo?'SAMPLE LISTING':esc(p.status==='Draft'?'PRIVATE DRAFT':p.status.toUpperCase())}</span>${!p.photo?'<small>Illustration</small>':''}</div><div class="cardbody"><div class="row"><span class="tag gray">${esc(p.type)} • ${esc(p.purpose)}</span><button aria-label="Save property" onclick="toggleSave('${p.id}')">${state.saved.includes(p.id)?'♥':'♡'}</button></div><h3 onclick="go('detail',{id:'${p.id}'})">${esc(p.title)}</h3><small>${icon('pin')} ${esc(p.village)}, ${esc(p.city||p.district)}</small><div class="meta"><span>${fmt(p.area)} ${esc(p.unit)}</span><span>${p.bhk?esc(p.bhk)+' BHK':esc(p.facing||'Facing not supplied')}</span></div><div class="row"><div class="price">${money(p.price)}${p.purpose==='Rent'?'<small> /month</small>':''}</div><button class="btn secondary" onclick="go('detail',{id:'${p.id}'})">View</button></div></div></article>`}
function filterListings(){return state.listings.filter(p=>(!view.mine||!p.demo)&&(view.type==='All'||p.type===view.type)&&(view.purpose==='All'||p.purpose===view.purpose)&&(!view.max||p.price<=Number(view.max))&&(!view.q||[p.title,p.village,p.city,p.district,p.survey,p.plotCode].join(' ').toLowerCase().includes(view.q.toLowerCase())))}
function setFilter(k,v){view[k]=v;home()}
function home(){const rows=filterListings();$('app').innerHTML=`<div class="hero"><div class="eyebrow">PROPERTY • LOCATION • DUE DILIGENCE</div><h1>${t('Find the right property. Know the plot.','సరైన ప్రాపర్టీని కనుగొనండి.')}</h1><p>${t('Property details, map locations and CRDA plot references in one simple place.','ప్రాపర్టీ వివరాలు, మ్యాప్ మరియు CRDA ప్లాట్ సమాచారం ఒకే చోట.')}</p><button class="btn" style="background:#edb76f;color:#7c2d12" onclick="go('edit')">${icon('plus')} ${t('List a property','ప్రాపర్టీ జోడించండి')}</button></div><form class="searchline" onsubmit="event.preventDefault();setFilter('q',this.q.value)"><input name="q" aria-label="Search properties" value="${esc(view.q)}" placeholder="Village, city, survey or plot code"><button class="btn" aria-label="Search">${icon('search')}</button></form><div class="chips">${['All','Plot','Apartment','House','Commercial','Farm land'].map(x=>`<button class="chip ${view.type===x?'active':''}" onclick="setFilter('type','${x}')">${x}</button>`).join('')}</div><details><summary>More filters ${view.mine?'• My properties':''}</summary><div class="grid"><div><label>Purpose</label><select onchange="setFilter('purpose',this.value)">${options(['All','Sale','Rent'],view.purpose)}</select></div><div><label>Maximum budget (INR)</label><input type="number" min="0" value="${esc(view.max)}" onchange="setFilter('max',this.value)"></div></div><div class="checkrow" style="margin-top:14px"><input id="mine" type="checkbox" ${view.mine?'checked':''} onchange="setFilter('mine',this.checked)"><label for="mine">Only my local properties</label></div></details><div class="row sectionhead"><h2>${t('Property listings','ప్రాపర్టీ లిస్టింగ్స్')}</h2><span class="count">${rows.length} results</span></div><div class="cards">${rows.map(card).join('')||empty('No properties match','Try a different place or add your own property.')}</div><p class="footertext">Standalone prototype. Listings you add stay on this device. Sample listings are fictional and their pins are approximate. CRDA records are reference plots, not sale offers.</p><button class="btn outline full" onclick="go('about')">Data sources & app information</button>`}
function options(a,v){return a.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function empty(h,p){return `<div class="empty">${icon('home')}<h3>${h}</h3><p class="muted">${p}</p></div>`}
function toggleSave(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];if(persist()){toast(state.saved.includes(id)?'Property saved':'Removed from saved');render()}}
function savedPage(){$('app').innerHTML=`<div class="eyebrow">YOUR SHORTLIST</div><h1>${t('Saved properties','సేవ్ చేసిన ప్రాపర్టీలు')}</h1><p class="muted">Your saved listing details and legal-check progress.</p><div class="cards">${state.listings.filter(p=>state.saved.includes(p.id)).map(card).join('')||empty('Your shortlist is empty','Tap the heart on any property to save it here.')}</div>`}
function fact(k,v){return `<div class="fact"><span>${k}</span><b>${v===undefined||v===null||v===''?'Not supplied':esc(v)}</b></div>`}
function detail(){const p=state.listings.find(x=>x.id===args.id);if(!p){$('app').innerHTML=empty('Property unavailable','Return to the property list.');return}const ref=state.refs.find(r=>r.code===p.plotCode);$('app').innerHTML=`${backbtn()}<div class="visual" style="height:220px;border-radius:18px;margin-bottom:17px">${p.photo?`<img src="${p.photo}" alt="Property photo">`:illustration(p)}<span class="tag ${p.demo?'amber':''}">${p.demo?'FICTIONAL SAMPLE':esc(p.status)}</span>${!p.photo?'<small>Illustration</small>':''}</div><div class="row"><span class="tag gray">${esc(p.type)} • ${esc(p.purpose)}</span><button onclick="toggleSave('${p.id}')">${state.saved.includes(p.id)?'♥ Saved':'♡ Save'}</button></div><h1>${esc(p.title)}</h1><p class="muted">${icon('pin')} ${esc(p.village)}, ${esc(p.city||p.district)}</p><div class="price">${money(p.price)}${p.purpose==='Rent'?'<small> /month</small>':''}</div><small>${p.area&&p.price?money(p.price/p.area)+' / '+esc(p.unit):''}</small>${p.demo?'<div class="notice">Fictional sample, not a genuine sale offer. Coordinates are approximate demonstration pins.</div>':'<div class="notice blue">Device-local listing. Owner-entered facts and asking price are not independently verified.</div>'}<div class="panel"><h2>Property details</h2><div class="facts">${fact('Area',fmt(p.area)+' '+p.unit)}${fact('Facing',p.facing)}${fact('Road width',p.road?fmt(p.road)+' m':null)}${fact('Bedrooms',p.bhk)}${fact('District',p.district)}${fact('Mandal',p.mandal)}${fact('Revenue village',p.village)}${fact('Availability',p.status)}${fact('CRDA plot code',p.plotCode)}${fact('Survey / subdivision',p.survey)}${fact('Approval reference',p.approval)}${fact('Document availability',p.documents||'Not supplied')}</div></div><div class="panel"><h2>About this property</h2><p>${esc(p.description||'No description supplied.')}</p><small>Public seller: ${esc(p.seller||'Not supplied')}</small></div>${ref?`<div class="notice blue">Linked CRDA reference: ${esc(ref.code)}<br><button class="btn secondary" onclick="go('ref',{id:'${ref.id}'})">View source plot & boundary</button></div>`:''}<div class="panel"><div class="row"><h2>Property location</h2><span class="tag gray">${p.demo?'Approximate demo pin':ref?'Imported GIS centre':'User-entered pin'}</span></div>${coords(p.lat,p.lon)?`<div id="detailmap" class="map" style="height:290px"></div><a class="btn outline full" href="${mapsURL(p)}">Open Google Maps / Directions</a><small>${Number(p.lat).toFixed(6)}, ${Number(p.lon).toFixed(6)}. Map position alone does not establish ownership.</small>`:'<p class="muted">No coordinates supplied. Edit this property to add a map pin.</p>'}</div><div class="panel"><h2>Legal search & checks</h2><p class="muted">Search official records and track the documents you have reviewed.</p><button class="btn full" onclick="go('legal',{id:'${p.id}'})">${icon('legal')} Open legal search</button></div><div class="row wrap"><button class="btn outline grow" onclick="shareProperty('${p.id}')">${icon('share')} Share details</button><button class="btn secondary grow" onclick="go('edit',{id:'${p.id}'})">Edit property</button></div>${!p.demo&&/^\d{10}$/.test(p.phone||'')?`<div class="stickyaction row"><a class="btn grow" href="tel:+91${p.phone}">Call seller</a><a class="btn secondary grow" href="https://wa.me/91${p.phone}?text=${encodeURIComponent('I am interested in '+p.title)}">WhatsApp</a></div>`:'<p class="footertext">No contact supplied. Sample listings do not include real seller phone numbers.</p>'}`;
 if(coords(p.lat,p.lon))makeMap('detailmap',[p],ref?[ref]:[],p.lat,p.lon,16)}
function mapsURL(p){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.lat+','+p.lon)}
function shareText(title,text){if(window.AndroidApp?.share)AndroidApp.share(title,text);else if(navigator.share)navigator.share({title,text}).catch(()=>{});else{navigator.clipboard?.writeText(text).then(()=>toast('Copied to clipboard')).catch(()=>showText(title,text))}}
function showText(title,text){$('app').innerHTML=`${backbtn()}<h2>${esc(title)}</h2><textarea readonly style="min-height:350px">${esc(text)}</textarea><p class="muted">Select and copy the text.</p>`}
function shareProperty(id){const p=state.listings.find(x=>x.id===id);shareText(p.title,`${p.demo?'FICTIONAL SAMPLE - NOT FOR SALE\n':''}${p.title}\n${p.village}, ${p.city||p.district}\n${p.area} ${p.unit} | ${money(p.price)}${p.purpose==='Rent'?' /month':''}\n${p.plotCode?'Plot: '+p.plotCode+'\n':''}${coords(p.lat,p.lon)?mapsURL(p):''}\nListing facts are seller supplied. Independently verify documents.`)}

function edit(){const p=state.listings.find(x=>x.id===args.id)||{};editorRef=args.ref?state.refs.find(r=>r.id===args.ref):null;editorCopy=editorRef?{...p,title:'Plot in '+editorRef.village,type:'Plot',purpose:'Sale',area:editorRef.area,unit:'sq yd',village:editorRef.village,city:'Amaravati',district:editorRef.district,mandal:editorRef.mandal,plotCode:editorRef.code,survey:editorRef.survey,road:editorRef.road,lat:editorRef.lat,lon:editorRef.lon}:p;const v=editorCopy;photoDraft=v.photo||'';
 $('app').innerHTML=`${backbtn()}<div class="eyebrow">PROPERTY LISTING</div><h1>${p.id?'Edit property':'Add a property'}</h1><div class="notice blue">Saved on this device. Imported plot data is reference information; enter your own asking price and authorized contact.</div><form id="propertyForm" onsubmit="saveProperty(event)"><div class="panel"><h2>Basic details</h2>${input('Title','title',v.title,'text',true)}<div class="grid">${select('Property type','type',['Plot','Apartment','House','Commercial','Farm land'],v.type||'Plot')}${select('Purpose','purpose',['Sale','Rent'],v.purpose||'Sale')}${input('Asking price (INR)','price',v.price,'number',true,'min="1" step="0.01"')}${input('Area','area',v.area?Number(v.area).toFixed(2):'','number',true,'min="0.01" step="0.01"')}${select('Area unit','unit',['sq yd','sq ft','sq m','acre'],v.unit||'sq yd')}${select('Availability','status',['Draft','Available','On hold','Sold','Rented'],v.status||'Draft')}</div></div><div class="panel"><h2>Location & plot identity</h2><div class="grid">${input('City','city',v.city||'Amaravati','text',true)}${input('District','district',v.district,'text',true)}${input('Mandal','mandal',v.mandal)}${input('Revenue village / locality','village',v.village,'text',true)}</div>${input('CRDA plot code (optional)','plotCode',v.plotCode)}${input('Survey / subdivision','survey',v.survey)}<div class="grid">${input('Latitude','lat',v.lat,'number',false,'step="any" min="-85" max="85"')}${input('Longitude','lon',v.lon,'number',false,'step="any" min="-180" max="180"')}</div><small>Enter exact coordinates from your documents, or pick an approximate pin below.</small><div class="space"></div><button class="btn secondary full" type="button" onclick="pickMap()">${icon('map')} Pick position on map</button><div id="pickmap" class="map" hidden></div></div><div class="panel"><h2>Property facts & documents</h2><div class="grid">${select('Facing','facing',['Not supplied','East','West','North','South','North East','North West','South East','South West'],v.facing||'Not supplied')}${input('Road width (metres)','road',v.road,'number',false,'min="0" step="0.1"')}${input('Bedrooms (where applicable)','bhk',v.bhk,'number',false,'min="0" max="20"')}${select('Documents','documents',['Not supplied','Available on request'],v.documents||'Not supplied')}</div>${input('Approval reference (seller supplied)','approval',v.approval)}<label>Description</label><textarea name="description" maxlength="2500">${esc(v.description||'')}</textarea><label>Photo (optional)</label><input type="file" accept="image/*" onchange="readPhoto(this)"><div id="photopreview">${photoDraft?`<img class="photo-preview" src="${photoDraft}" alt="Selected property">`:''}</div></div><div class="panel"><h2>Seller contact</h2>${input('Public seller / business name','seller',v.seller)}${input('Public mobile (optional, 10 digits)','phone',v.phone,'tel',false,'pattern="[6-9][0-9]{9}" maxlength="10"')}<small>Only enter a phone number you are authorized to display in this local listing.</small></div><button class="btn full" type="submit">Save property on device</button>${p.id?`<button type="button" class="btn danger full" style="margin-top:10px" onclick="deleteProperty('${p.id}')">Delete this local property</button>`:''}</form>`}
function input(l,n,v,type='text',req=false,extra=''){return `<div><label for="f_${n}">${l}${req?' *':''}</label><input id="f_${n}" name="${n}" type="${type}" value="${esc(v??'')}" ${req?'required':''} ${extra} maxlength="250"></div>`}
function select(l,n,a,v){return `<div><label for="f_${n}">${l}</label><select name="${n}" id="f_${n}">${options(a,v)}</select></div>`}
function saveProperty(e){e.preventDefault();const f=new FormData(e.target),old=state.listings.find(p=>p.id===args.id),v=Object.fromEntries(f);for(const k of ['price','area','lat','lon','road','bhk'])v[k]=num(v[k]);v.plotCode=canonical(v.plotCode);if(v.plotCode&&!/^\d{1,3}-\d{1,4}-\d{1,5}-\d{1,5}-[A-Z0-9]{1,8}$/.test(v.plotCode)){toast('Use the CRDA plot-code format shown on your record.');return}if((v.lat!==null||v.lon!==null)&&!coords(v.lat,v.lon)){toast('Supply both valid latitude and longitude.');return}if(v.status==='Available'&&['Plot','Farm land'].includes(v.type)&&v.purpose==='Sale'&&!v.survey&&!v.plotCode){toast('Add a survey number or CRDA plot code before marking land available.');return}const p={...old,...v,id:old?.id||uid('p'),demo:old?.demo||false,photo:photoDraft,updatedAt:new Date().toISOString()};if(old)state.listings=state.listings.map(x=>x.id===p.id?p:x);else state.listings.unshift(p);if(persist()){toast('Property saved on this device');route='detail';args={id:p.id};render();window.scrollTo(0,0)}}
function deleteProperty(id){if(!confirm('Delete this local property and its private checklist?'))return;state.listings=state.listings.filter(p=>p.id!==id);state.saved=state.saved.filter(x=>x!==id);delete state.checks[id];delete state.notes[id];if(persist()){route='home';args={};stack=[];render();toast('Property deleted')}}
async function readPhoto(el){const file=el.files[0];if(!file)return;if(file.size>8*1024*1024){toast('Choose a photo below 8 MB.');return}try{const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});const img=await new Promise((res,rej)=>{let i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=data});const c=document.createElement('canvas'),s=Math.min(1,1000/img.width,1000/img.height);c.width=img.width*s;c.height=img.height*s;c.getContext('2d').drawImage(img,0,0,c.width,c.height);photoDraft=c.toDataURL('image/jpeg',.7);$('photopreview').innerHTML=`<img class="photo-preview" src="${photoDraft}" alt="Selected property photo"><button type="button" onclick="photoDraft='';$('photopreview').innerHTML=''">Remove photo</button>`}catch(e){toast('This file is not a supported photo.')}}

let maps={};
function world(lat,lon,z){let s=256*2**z, sin=Math.sin(lat*Math.PI/180);return [(lon+180)/360*s,(.5-Math.log((1+sin)/(1-sin))/(4*Math.PI))*s]}
function unworld(x,y,z){let s=256*2**z;return [180/Math.PI*Math.atan(Math.sinh(Math.PI*(1-2*y/s))),x/s*360-180]}
function makeMap(id,listings,refs,lat=16.51,lon=80.47,z=13,pick=null){if(!$(id))return;maps[id]={id,listings,refs,lat,lon,z,pick};const el=$(id);el.innerHTML='<div class="maptiles"></div><div class="mapoverlay"></div><div class="mapcontrols"><button type="button" aria-label="Zoom in" onclick="zoomMap(\''+id+'\',1)">+</button><button type="button" aria-label="Zoom out" onclick="zoomMap(\''+id+'\',-1)">−</button></div><div class="mapcaption">'+(pick?'Tap map to set a pin':'Drag to explore • tap a pin for details')+'</div><div class="mapcredit"><span class="mapstatus">Street tiles require internet</span><a href="https://www.openstreetmap.org/copyright">© OpenStreetMap contributors</a></div>';drawMap(id);let start=null;
 el.onpointerdown=e=>{if(e.target.closest('button,a'))return;start={x:e.clientX,y:e.clientY,lat:maps[id].lat,lon:maps[id].lon};el.setPointerCapture(e.pointerId)};
 el.onpointerup=e=>{if(!start)return;let dx=e.clientX-start.x,dy=e.clientY-start.y;const m=maps[id];if(Math.abs(dx)+Math.abs(dy)>8){let w=world(start.lat,start.lon,m.z);[m.lat,m.lon]=unworld(w[0]-dx,w[1]-dy,m.z);m.lat=Math.max(-84,Math.min(84,m.lat));m.lon=((m.lon+540)%360)-180;drawMap(id)}else if(m.pick){let r=el.getBoundingClientRect(),w=world(m.lat,m.lon,m.z),ll=unworld(w[0]+e.clientX-r.left-r.width/2,w[1]+e.clientY-r.top-r.height/2,m.z);m.pick(...ll)}start=null};el.onpointercancel=()=>start=null;
}
function zoomMap(id,d){let m=maps[id];m.z=Math.max(4,Math.min(19,m.z+d));drawMap(id)}
function drawMap(id){let m=maps[id],el=$(id);if(!el)return;const w=el.clientWidth,h=el.clientHeight,c=world(m.lat,m.lon,m.z),left=c[0]-w/2,top=c[1]-h/2,N=2**m.z;let tiles='';for(let x=Math.floor(left/256);x<=Math.floor((left+w)/256);x++)for(let y=Math.floor(top/256);y<=Math.floor((top+h)/256);y++){if(y<0||y>=N)continue;tiles+=`<img alt="" referrerpolicy="strict-origin-when-cross-origin" src="https://tile.openstreetmap.org/${m.z}/${((x%N)+N)%N}/${y}.png" style="left:${x*256-left}px;top:${y*256-top}px" onload="this.closest('.map').querySelector('.mapstatus').textContent='Street map • zoom ${m.z}'" onerror="this.remove()">`}
 el.querySelector('.maptiles').innerHTML=tiles;let polygons='',pins='';for(const r of m.refs){if(r.rings?.length){polygons+=`<path d="${r.rings.map(ring=>ring.map((p,i)=>{let q=world(p[1],p[0],m.z);return `${i?'L':'M'}${q[0]-left},${q[1]-top}`}).join(' ')+' Z').join(' ')}" fill="#e8aa5350" fill-rule="evenodd" stroke="#b78234" stroke-width="2"/>`}if(coords(r.lat,r.lon)){let q=world(r.lat,r.lon,m.z);if(q[0]-left>-100&&q[0]-left<w+100&&q[1]-top>-50&&q[1]-top<h+50)pins+=`<button class="refpin" aria-label="Plot ${esc(r.code)}" style="left:${q[0]-left}px;top:${q[1]-top}px" onclick="go('ref',{id:'${r.id}'})">${esc(r.code)}</button>`}}
 for(const p of m.listings){if(!coords(p.lat,p.lon))continue;let q=world(p.lat,p.lon,m.z);if(q[0]-left>-100&&q[0]-left<w+100&&q[1]-top>-50&&q[1]-top<h+50)pins+=`<button style="left:${q[0]-left}px;top:${q[1]-top}px" onclick="go('detail',{id:'${p.id}'})">${p.demo?'DEMO • ':''}${money(p.price)}</button>`}
 if(m.pick&&coords($('f_lat')?.value,$('f_lon')?.value)){let q=world(+$('f_lat').value,+$('f_lon').value,m.z);polygons+=`<circle cx="${q[0]-left}" cy="${q[1]-top}" r="9" fill="#ea580c" stroke="white" stroke-width="3"/>`}
 el.querySelector('.mapoverlay').innerHTML=`<svg>${polygons}</svg>${pins}`;
}
function pickMap(){const el=$('pickmap');el.hidden=false;const la=$('f_lat'),lo=$('f_lon');makeMap('pickmap',[],[],coords(la.value,lo.value)?+la.value:16.51,coords(la.value,lo.value)?+lo.value:80.47,15,(lat,lon)=>{la.value=lat.toFixed(7);lo.value=lon.toFixed(7);drawMap('pickmap');toast('Approximate pin selected. Verify exact boundaries independently.');});el.scrollIntoView({behavior:'smooth',block:'center'})}
function mapPage(){const mode=args.mode||'all',ls=mode==='refs'?[]:state.listings.filter(p=>p.status==='Available'),rs=mode==='listings'?[]:state.refs;let focus=args.ref?state.refs.find(r=>r.id===args.ref):null;if(!focus&&args.id)focus=state.listings.find(p=>p.id===args.id);const initial=focus||rs.find(r=>coords(r.lat,r.lon))||ls.find(p=>coords(p.lat,p.lon));$('app').innerHTML=`<div class="eyebrow">PROPERTY & PLOT EXPLORER</div><h1>${t('Explore on the map','మ్యాప్‌లో చూడండి')}</h1><div class="chips">${[['all','All pins'],['listings','Property listings'],['refs','CRDA boundaries']].map(([x,l])=>`<button class="chip ${mode===x?'active':''}" onclick="args.mode='${x}';mapPage()">${l}</button>`).join('')}</div><div id="mainmap" class="map"></div><div class="notice blue">Teal: local property listings. Gold: imported CRDA reference plots, not sale offers. Official GIS boundaries are source information, not a ground survey.</div><div class="panel"><h3>Located records</h3><small>${ls.filter(p=>coords(p.lat,p.lon)).length} listing pins • ${rs.filter(r=>coords(r.lat,r.lon)).length} reference plots</small>${rs.slice(0,15).map(r=>`<div class="listrow" onclick="go('ref',{id:'${r.id}'})"><strong>${esc(r.code)}</strong><small>${esc(r.village)} • ${fmt(r.area)} sq yd</small></div>`).join('')}${ls.slice(0,8).map(p=>`<div class="listrow" onclick="go('detail',{id:'${p.id}'})"><strong>${esc(p.title)}</strong><small>${p.demo?'Sample • ':''}${esc(p.village)} • ${money(p.price)}</small></div>`).join('')}</div>`;makeMap('mainmap',ls,rs,initial?.lat||16.51,initial?.lon||80.47,focus?18:13)}

const PORTALS=[['CRDA plot / mutation lookup','https://crda.ap.gov.in/apcrdav2/Views/KnowYourPlot.aspx','Plot code lookup on official portal; CAPTCHA is entered there.'],['AP encumbrance certificate search','https://registration.ec.ap.gov.in/ecSearch','Search the required property and period on the official portal.'],['AP MeeBhoomi revenue records','https://meebhoomi.ap.gov.in/','Check revenue identifiers against your documents.'],['AP Registration department','https://registration.ap.gov.in/','Registration information and department services.'],['AP RERA project search','https://rera.ap.gov.in/RERA/Views/index.html','Use where RERA registration applies.']];
const CHECKS=['Plot identity & boundaries','Seller authority and title documents','Encumbrance records','Revenue / mutation records','Land use and approvals','Taxes, dues and disputes','Independent professional review'];
function legal(){const p=state.listings.find(x=>x.id===args.id),r=state.refs.find(x=>x.id===args.ref),item=p||r,id=item?.id;const ck=state.checks[id]||{},done=Object.values(ck).filter(x=>x==='Reviewed').length;let query=args.q||'';const matches=query?state.refs.filter(x=>[x.code,x.village,x.survey].join(' ').toLowerCase().includes(query.toLowerCase())).slice(0,25):[];
 $('app').innerHTML=`${id?backbtn():''}<div class="eyebrow">IDENTITY • RECORDS • DOCUMENTS</div><h1>${t('Legal search','లీగల్ సెర్చ్')}</h1><p class="muted">Find plot references and open the official record searches.</p><div class="panel"><h3>Search imported CRDA references</h3><form class="searchline" onsubmit="event.preventDefault();args.q=this.q.value;legal()"><input name="q" value="${esc(query)}" placeholder="Plot code, village or survey number" aria-label="Legal reference search"><button class="btn">Search</button></form>${query?matches.map(x=>`<div class="listrow" onclick="go('ref',{id:'${x.id}'})"><strong>${esc(x.code)}</strong><small>${esc(x.village)} • survey ${esc(x.survey||'not supplied')}</small></div>`).join('')||'<p class="muted">No cached reference matches. Use CRDA plots to fetch the plot code.</p>':'<small>Searches only the reference records saved on this device.</small>'}</div>${item?`<div class="panel"><h3>Identifiers for your search</h3><div class="facts">${fact('Plot code',p?.plotCode||r?.code)}${fact('Village',item.village)}${fact('Survey / subdivision',item.survey)}${fact('District / mandal',[item.district,item.mandal].filter(Boolean).join(' / '))}</div><button class="btn secondary full" style="margin-top:12px" onclick="copyIdentity()">Copy identifiers</button></div>`:''}<div class="notice">These searches do not issue a title clearance. Official portals may require login or CAPTCHA. Complete those steps in your browser; this app does not bypass them.</div><div class="panel linklist"><h2>Official search portals</h2>${PORTALS.map(([l,u,d])=>`<a href="${u}"><strong>${esc(l)} ↗</strong><small>${esc(d)}</small></a>`).join('')}</div>${id?`<div class="panel"><h2>My private due-diligence checklist</h2><small>${done}/${CHECKS.length} marked reviewed. This tracks your own review, not a legal verdict.</small><div class="legalprogress"><span style="width:${done/CHECKS.length*100}%"></span></div>${CHECKS.map((l,i)=>`<div class="checkitem"><label>${l}</label><select onchange="setCheck('${id}',${i},this.value)">${options(['Not started','Requested','Reviewed'],ck[i]||'Not started')}</select></div>`).join('')}<label>Private review notes</label><textarea id="legalnote" maxlength="4000" placeholder="Document references, questions and professional-review notes">${esc(state.notes[id]||'')}</textarea><button class="btn full" style="margin-top:12px" onclick="saveNote('${id}')">Save private notes</button></div>`:`<div class="panel"><h3>Start with a property</h3><p class="muted">Open a listing or CRDA reference to see its identifiers and save a private review checklist.</p><button class="btn secondary" onclick="go('home')">Browse properties</button></div>`}`}
function setCheck(id,i,v){(state.checks[id]??={})[i]=v;persist();const notes=$('legalnote')?.value;legal();if(notes!==undefined)$('legalnote').value=notes;toast('Checklist updated')}
function saveNote(id){state.notes[id]=$('legalnote').value;if(persist())toast('Private notes saved on device')}
function copyIdentity(){const p=state.listings.find(x=>x.id===args.id)||state.refs.find(x=>x.id===args.ref);if(!p)return;let text=`Plot: ${p.plotCode||p.code||'Not supplied'}\nVillage: ${p.village||''}\nSurvey: ${p.survey||''}\nDistrict: ${p.district||''}\nMandal: ${p.mandal||''}`;if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>toast('Identifiers copied')).catch(()=>shareText('Property identifiers',text));else shareText('Property identifiers',text)}

function crda(){const q=args.q||'',rs=state.refs.filter(r=>!q||[r.code,r.village,r.survey].join(' ').toLowerCase().includes(q.toLowerCase()));$('app').innerHTML=`<div class="hero"><div class="eyebrow">CRDA PLOT REFERENCE DESK</div><h1>${t('Import plot data. Fill details faster.','CRDA ప్లాట్ వివరాలు దిగుమతి చేయండి.')}</h1><p>Plot identity, area, village and GIS boundaries. No owner IDs or private contact data imported.</p></div><div class="grid"><div class="stat"><div class="pillcount">${state.refs.length}</div><small>reference plots saved</small></div><div class="stat"><div class="pillcount">${state.imports.length}</div><small>completed import batches</small></div></div><div class="notice">Reference catalogue only. CRDA records do not imply that a plot is for sale or that a seller owns it. Dataset vintage and last import time are shown per plot.</div><div class="panel"><h2>Auto-import from official GIS</h2><p class="muted mini">Exact plot code or village search. Each batch fetches up to 100 records, with resume for more.</p><label>CRDA plot code</label><input id="syncCode" value="${esc(sync.code)}" placeholder="e.g. 13-535-2974-11-C18"><label>Or village / LPS village</label><input id="syncVillage" value="${esc(sync.village)}" placeholder="e.g. Thullur"><div class="space"></div><button id="fetchbtn" class="btn full" ${sync.busy?'disabled':''} onclick="fetchGIS(false)">${sync.busy?'Fetching official records…':'Fetch & preview plot data'}</button>${sync.auto?'<button class="btn danger full" style="margin-top:8px" onclick="stopSync()">Stop automatic continuation</button>':''}${sync.offset&&!sync.done?`<button class="btn secondary full" style="margin-top:9px" onclick="fetchGIS(true)">Fetch next batch • offset ${sync.offset}</button>`:''}<small>Source: APCRDA GIS, LSP19Aug2026 / layer 0. Layer name references Nov 2018. A recent fetch does not mean all records are current.</small><div id="syncstatus" class="tabnote">${sync.done?'Last search complete.':sync.loaded?'Last fetch: '+sync.loaded+' records.':''}</div></div><details><summary>Import CSV / GeoJSON / ArcGIS JSON</summary><p class="mini muted">File must contain plot_code. Optional columns: village, district, mandal, rs_no, extn_sqyrd, rd_width_m, latitude, longitude. Geometry must use WGS84 (EPSG:4326).</p><input type="file" accept=".csv,.json,.geojson,text/csv,application/json" onchange="readImport(this)"><label>Or paste records</label><textarea id="importText" placeholder="plot_code,village,extn_sqyrd,latitude,longitude"></textarea><button class="btn secondary full" onclick="parseImport($('importText').value)">Preview pasted data</button><button class="btn outline full" style="margin-top:8px" onclick="shareTemplate()">Copy / share CSV template</button></details><form class="searchline" onsubmit="event.preventDefault();args.q=this.q.value;crda()"><input name="q" value="${esc(q)}" placeholder="Search saved plot codes or villages"><button class="btn" aria-label="Search saved CRDA plots">${icon('search')}</button></form><div class="row sectionhead"><h2>Imported plot references</h2><span class="count">${rs.length} results</span></div><div class="panel">${rs.slice(0,100).map(r=>`<div class="listrow" onclick="go('ref',{id:'${r.id}'})"><div class="row"><strong>${esc(r.code)}</strong><span class="tag amber">REFERENCE</span></div><small>${esc(r.village||'Village not supplied')} • ${fmt(r.area)} sq yd</small><small>${esc(r.source)} • ${new Date(r.importedAt).toLocaleDateString('en-IN')}</small></div>`).join('')||empty('No imported plots','Fetch a plot code or import a file to start.')}</div>${rs.length>100?'<p class="muted">Showing first 100. Refine the search to find another plot.</p>':''}<details><summary>Import history & data export</summary>${state.imports.slice(0,10).map(x=>`<div class="history">${esc(x.source)}<br>${x.added} added • ${x.updated} updated • ${x.rejected} rejected<br><small>${new Date(x.at).toLocaleString('en-IN')}</small></div>`).join('')||'<p class="muted">Bundled GIS snapshot is separate from user imports.</p>'}<button class="btn secondary full" onclick="exportRefs()">Share plot references as JSON</button></details><button class="btn outline full" onclick="go('about')">Source & privacy information</button>`}
function sqlValue(s){return clean(s).replace(/'/g,"''")}
async function fetchGIS(next){if(sync.busy)return;const code=canonical($('syncCode')?.value??sync.code),village=clean($('syncVillage')?.value??sync.village);if(!code&&!village){toast('Enter a plot code or village.');return}if(code&&!/^\d{1,3}-\d{1,4}-\d{1,5}-\d{1,5}-[A-Z0-9]{1,8}$/.test(code)){toast('Enter the exact CRDA plot code from your record.');return}if(next&&(sync.code!==code||sync.village!==village)){toast('Filters changed. Fetch the first batch for this search.');return}if(!next){sync.offset=0;sync.done=false}sync.code=code;sync.village=village;sync.busy=true;crda();let where=code?`UPPER(plot_code)='${sqlValue(code)}'`:`(UPPER(village) LIKE '%${sqlValue(village.toUpperCase()).replace(/[%_]/g,'')}%' OR UPPER(lpsvillage) LIKE '%${sqlValue(village.toUpperCase()).replace(/[%_]/g,'')}%')`;const params=new URLSearchParams({where,outFields:FIELDS,returnGeometry:'true',outSR:'4326',resultRecordCount:'100',resultOffset:String(sync.offset),orderByFields:'objectid ASC',f:'json'});try{const abort=new AbortController(),tm=setTimeout(()=>abort.abort(),35000);let d;try{const res=await fetch('/crda-query?'+params,{signal:abort.signal});if(!res.ok)throw Error('Official GIS request failed');d=await res.json()}finally{clearTimeout(tm)}if(d.error)throw Error(d.error.message||'GIS service rejected this request');if(!Array.isArray(d.features))throw Error('Unexpected GIS response. Import a file instead.');sync.loaded=d.features.length;if(!d.features.length){sync.done=true;sync.busy=false;crda();toast('No plot records matched this search.');return}preview=prepare(d.features,'CRDA GIS live import');preview.nextOffset=sync.offset+d.features.length;preview.complete=!d.exceededTransferLimit;sync.busy=false;if(sync.auto&&sync.remaining>0){sync.remaining--;applyImport()}else{sync.auto=false;go('preview')}}catch(e){sync.busy=false;sync.auto=false;crda();$('syncstatus').textContent=e.name==='AbortError'?'Service timed out. Retry or use file import.':e.message;toast('Could not complete live import. No records were changed.')}}
function prepare(rows,source){const records=[],errors=[],seen=new Set();let duplicates=0;for(let i=0;i<rows.length;i++){try{const r=normalize(rows[i],source);if(seen.has(r.code)){duplicates++;continue}seen.add(r.code);records.push(r)}catch(e){errors.push(`Row ${i+1}: ${e.message}`)}}return {records,errors,duplicates,source,total:rows.length,updated:records.filter(r=>state.refs.some(x=>x.code===r.code)).length}}
function parseCSV(text){const rows=[];let row=[],val='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){val+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(val);val=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(val);if(row.some(v=>v.trim()))rows.push(row);row=[];val=''}else val+=c}if(quote)throw Error('CSV has an unclosed quote');row.push(val);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw Error('CSV needs a header and at least one record');const keys=rows.shift().map(x=>x.replace(/^\uFEFF/,'').trim());return rows.map(r=>Object.fromEntries(keys.map((k,i)=>[k,r[i]??''])))}
function parseImport(text){try{if(!text.trim())throw Error('Paste or select a data file first');if(text.length>2*1024*1024)throw Error('File is too large. Use batches below 2 MB.');let rows;if(/^[\[{]/.test(text.trim())){const d=JSON.parse(text);rows=Array.isArray(d)?d:d.features||d.records;if(!Array.isArray(rows))throw Error('JSON must be an array or contain features/records');if(d.spatialReference&&!['4326',4326].includes(d.spatialReference.wkid))throw Error('Export the file in EPSG:4326 before importing');}else rows=parseCSV(text);if(rows.length>1000)throw Error('Use batches of at most 1,000 records');preview=prepare(rows,'User file import');go('preview')}catch(e){toast(e.message)}}
async function readImport(el){const f=el.files[0];if(!f)return;if(f.size>2*1024*1024){toast('Choose a file below 2 MB.');return}try{parseImport(await f.text())}catch(e){toast('Unable to read this file.')}}
function previewPage(){if(!preview){route='crda';crda();return}const p=preview;$('app').innerHTML=`${backbtn()}<div class="eyebrow">REVIEW BEFORE IMPORT</div><h1>Plot migration preview</h1><p class="muted">${esc(p.source)}. Only whitelisted plot facts and coordinates are retained.</p><div class="grid"><div class="stat"><div class="pillcount">${p.records.length-p.updated}</div><small>new references</small></div><div class="stat"><div class="pillcount">${p.updated}</div><small>existing references to update</small></div></div><div class="notice">${p.errors.length} invalid rows • ${p.duplicates} duplicate rows skipped. No sale listings will be created. Existing property prices, contacts and private legal notes remain independent.</div><div class="panel scroll"><table class="previewtable"><thead><tr><th>Plot code</th><th>Village / area</th><th>Map</th></tr></thead><tbody>${p.records.slice(0,30).map(r=>`<tr><td>${esc(r.code)}</td><td>${esc(r.village)}<br>${fmt(r.area)} sq yd</td><td>${coords(r.lat,r.lon)?'Located':'No pin'}</td></tr>`).join('')}</tbody></table></div>${p.records.length>30?'<small>Preview shows 30 rows; all valid rows in this batch will import.</small>':''}${p.errors.length?`<details><summary>Rejected rows</summary><p class="mini">${p.errors.slice(0,20).map(esc).join('<br>')}</p></details>`:''}${p.nextOffset!==undefined&&!p.complete&&!sync.code?'<div class="panel checkrow"><input type="checkbox" id="continueBatches"><label for="continueBatches">Automatically import up to four more batches for this village (500 plots maximum per run). Existing references will update.</label></div>':''}<button class="btn full" ${!p.records.length?'disabled':''} onclick="applyImport()">Import ${p.records.length} valid reference plots</button><button class="btn outline full" style="margin-top:10px" onclick="back()">Cancel without changes</button>`}
function applyImport(){if(!preview)return;if($('continueBatches')?.checked){sync.auto=true;sync.remaining=4}const p=preview;let index=new Map(state.refs.map(r=>[r.code,r]));for(const r of p.records)index.set(r.code,r);state.refs=[...index.values()];state.imports.unshift({at:new Date().toISOString(),source:p.source,added:p.records.length-p.updated,updated:p.updated,rejected:p.errors.length});state.imports=state.imports.slice(0,30);if(!persist())return;if(p.nextOffset!==undefined){sync.offset=p.nextOffset;sync.done=p.complete}preview=null;route='crda';args={};render();window.scrollTo(0,0);toast('Plot reference batch imported successfully');if(sync.auto&&!sync.done&&sync.remaining>0)setTimeout(()=>{if(sync.auto)fetchGIS(true)},150);else sync.auto=false}
function shareTemplate(){shareText('CRDA plot CSV template','plot_code,village,district,mandal,rs_no,extn_sqyrd,rd_width_m,latitude,longitude\nReplace with your authorized record values; geometry must be WGS84.\nDo not include Aadhaar, owner names or phone numbers.')}
function exportRefs(){const rows=state.refs.map(r=>({plot_code:r.code,village:r.village,district:r.district,mandal:r.mandal,rs_no:r.survey,extn_sqyrd:r.area,rd_width_m:r.road,latitude:r.lat,longitude:r.lon,geometry:r.rings.length?{rings:r.rings}:undefined}));shareText('Agent Mart plot reference export',JSON.stringify({spatialReference:{wkid:4326},records:rows},null,2))}
function refDetail(){const r=state.refs.find(x=>x.id===args.id);if(!r){$('app').innerHTML=empty('Plot unavailable','Return to CRDA plots.');return}$('app').innerHTML=`${backbtn()}<div class="refdetail"><span class="tag amber">CRDA REFERENCE • NOT A SALE OFFER</span><h1 class="break">${esc(r.code)}</h1><p>${esc(r.village||'Village not supplied')} • ${esc(r.district)}</p><div class="price">${fmt(r.area)} <small>sq yd</small></div><small>${esc(r.landUse||'Land use not supplied')}</small></div><div class="panel"><h2>Imported plot facts</h2><div class="facts">${fact('Plot number',r.plotNo)}${fact('Survey references',r.survey)}${fact('Township',r.township)}${fact('Colony / block',[r.colony,r.block].join(' / '))}${fact('District',r.district)}${fact('Mandal',r.mandal)}${fact('GIS area',r.areaSqm?fmt(r.areaSqm)+' sq m':null)}${fact('Road width',r.road?fmt(r.road)+' m':'Not supplied / zero in source')}${fact('Zoning',r.zoning)}${fact('Data source',r.source)}</div></div><div class="panel"><h2>Plot boundary & location</h2>${coords(r.lat,r.lon)?`<div id="refmap" class="map" style="height:320px"></div><a class="btn outline full" href="${mapsURL(r)}">Open coordinates in Google Maps</a><small>${r.rings.length?'Gold boundary: imported polygon.':'No polygon supplied; only coordinate shown.'} A GIS boundary is not a physical survey.</small>`:'<p class="muted">No WGS84 coordinates supplied. You can add a pin when creating your listing.</p>'}</div><div class="notice blue">Imported ${new Date(r.importedAt).toLocaleString('en-IN')}. ${r.source.startsWith('CRDA')?'Official layer: LSP19Aug2026; layer name sde.sde.LPS_Plots_Nov2018_FC.':'User-imported source; not independently authenticated.'} An import date does not establish present ownership, availability or title.</div><div class="row wrap"><button class="btn grow" onclick="go('edit',{ref:'${r.id}'})">Use to create property draft</button><button class="btn secondary grow" onclick="go('legal',{ref:'${r.id}'})">Legal search</button></div><p class="footertext">Only plot facts and coordinates are stored. Owner names, Aadhaar and private contact fields are excluded.</p><a class="btn outline full" href="${GIS}">View official GIS layer metadata</a>`;if(coords(r.lat,r.lon))makeMap('refmap',[],[r],r.lat,r.lon,18)}
function aboutPage(){$('app').innerHTML=`${backbtn()}<div class="eyebrow">AGENT MART PROPERTY • 2.0</div><h1>Data & app information</h1><div class="panel"><h3>Focused property prototype</h3><p>Property listings, full details, street maps, legal-search tools and CRDA reference import. No farm marketplace, CRM or commission modules.</p><p class="mini muted">Properties, reference imports, saved items and checklists are stored on this device. There is no live multi-user listing backend or government certification.</p></div><div class="panel linklist"><h3>Official data sources</h3><a href="${GIS}">APCRDA GIS plot layer<small>LSP19Aug2026 / layer 0; plot_code, village, area and WGS84 geometry. Source layer name references Nov 2018.</small></a>${PORTALS.map(([l,u])=>`<a href="${u}">${l} ↗</a>`).join('')}<a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors<small>Live street tiles require internet. No offline tile bulk download.</small></a></div><div class="panel"><h3>Data safeguards</h3><p class="mini">Import uses a fixed allowlist of plot attributes. Aadhaar, owner names, phone numbers and private document contents are never requested by the live connector. CSV/JSON imports also discard unknown fields.</p><p class="mini">Public GIS data is a reference, not evidence of seller authority or a clear title. Official legal portals may require login and CAPTCHA. The app opens these in your external browser.</p></div><div class="notice">Prototype signing key and package are separate from the earlier Agent Mart app. This build installs alongside it. Do not use sample listings as genuine offers.</div>`}
render();

function stopSync(){sync.auto=false;toast("Automatic continuation stopped")}

// Firm workspace. Live records are held in memory; demo data has a separate store.
const Firm={mode:'local',token:'',endpoint:localStorage.getItem('firm_endpoint_300')||'',data:null,lastSync:'',busy:false,stale:false,editVersion:null,pending:new Map(),retries:new Map(),demoUser:'do'};
const original={header,render,home,detail,edit,saveProperty,deleteProperty,persist};
function enterprise(){return Firm.mode==='demo'||(Firm.mode==='live'&&!!Firm.token&&!!Firm.data?.firm)}
function role(){return Firm.data?.user?.role||'viewer'}
function manager(){return ['owner','manager'].includes(role())}
function writable(){return ['owner','manager','agent'].includes(role())}
function privateKey(){return 'firm_private_'+hash(Firm.endpoint+'|'+(Firm.data?.user?.id||'demo'))}
function firmReceive(id,result){const p=Firm.pending.get(id);if(!p)return;Firm.pending.delete(id);clearTimeout(p.timer);p.resolve(result)}window.firmReceive=firmReceive;
async function firmCall(method,path,body={},key=''){
 if(!Firm.endpoint)throw Error('Set your deployed HTTPS backend URL first.');
 let response;
 if(window.AndroidApp?.firmRequest){response=await new Promise((resolve,reject)=>{const id=uid('req'),timer=setTimeout(()=>{Firm.pending.delete(id);reject(Error('Server timed out. Keep this form open and retry.'))},path.startsWith('/api/intelligence/')?100000:45000);Firm.pending.set(id,{resolve,timer});AndroidApp.firmRequest(JSON.stringify({id,method,path,body,token:Firm.token,key,origin:Firm.endpoint}))})}
 else {const ctrl=new AbortController(),tm=setTimeout(()=>ctrl.abort(),path.startsWith('/api/intelligence/')?100000:35000);try{const res=await fetch(Firm.endpoint+path,{method,headers:{'Content-Type':'application/json',...(Firm.token?{Authorization:'Bearer '+Firm.token}:{}),...(key?{'Idempotency-Key':key}:{})},body:method==='GET'?undefined:JSON.stringify(body),signal:ctrl.signal});response={status:res.status,data:await res.json()}}finally{clearTimeout(tm)}}
 if(response.status<200||response.status>=300){const e=Error(response.data?.error||'Server connection failed');e.status=response.status;if(response.status===401&&Firm.token){Firm.token='';Firm.data=null;Firm.mode='local';restoreLocal();route='firm';render()}throw e}return response.data;
}
function restoreLocal(){try{state=JSON.parse(localStorage.getItem(KEY))||state}catch(e){}lastGood=JSON.stringify(state)}
function useFirmView(){if(!enterprise()||!Firm.data)return;let rows=Firm.data.properties||[];if(Firm.mode==='demo'&&role()==='agent')rows=rows.filter(p=>p.assignedTo===Firm.data.user.id);state.listings=rows;}
persist=function(){if(!enterprise())return original.persist();try{const base=JSON.parse(localStorage.getItem(KEY)||lastGood);base.refs=state.refs;base.imports=state.imports;base.lang=state.lang;base.seeded=state.seeded;localStorage.setItem(KEY,JSON.stringify(base));localStorage.setItem(privateKey(),JSON.stringify({saved:state.saved,checks:state.checks,notes:state.notes}));if(Firm.mode==='demo')saveDemo();return true}catch(e){toast('Device storage is full. Export reference data and remove unused photos.');return false}};
function loadPrivate(){let p={};try{p=JSON.parse(localStorage.getItem(privateKey())||'{}')}catch(e){}state.saved=p.saved||[];state.checks=p.checks||{};state.notes=p.notes||{}}
async function firmRefresh(redraw=true){if(!Firm.token||Firm.busy)return;Firm.busy=true;const sessionToken=Firm.token;try{const d=await firmCall('GET','/api/sync');if(Firm.token!==sessionToken||Firm.mode!=='live')return;Firm.data=d;Firm.lastSync=new Date().toISOString();Firm.stale=false;useFirmView();if(redraw)render()}catch(e){Firm.stale=true;toast(e.message)}finally{Firm.busy=false}}
function statusStrip(){return `<div class="firmstrip ${Firm.mode==='demo'?'demostrip':''}"><span>${Firm.mode==='demo'?'OFFLINE FIRM DEMO':'SHARED FIRM WORKSPACE'} • ${esc(role().toUpperCase())}</span><span>${Firm.mode==='demo'?'Simulated access':Firm.stale?'Connection lost':'Synced '+(Firm.lastSync?new Date(Firm.lastSync).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'')}</span></div>`}
header=function(){original.header();$('header').querySelector('.brand strong').textContent='Agent Mart Firms';$('header').querySelector('.brand small').textContent=enterprise()?Firm.data.firm.name:'PROPERTY • TEAMS • WORKSPACE';const plus=$('header').querySelector('button[aria-label="Add property"]');if(enterprise()&&!writable())plus.style.display='none';$('header').insertAdjacentHTML('beforeend',`<button class="iconbtn" aria-label="Firm workspace" onclick="go('firm')">${icon('crda')}</button>`);
 if(enterprise()){const active=['firm','home','leads','visits','firmMore'].includes(route)?route:['leadEdit'].includes(route)?'leads':route==='visitEdit'?'visits':['detail','edit'].includes(route)?'home':'firmMore';$('nav').innerHTML=[['firm','home','Dashboard'],['home','search','Properties'],['leads','legal','Enquiries'],['visits','pin','Visits'],['firmMore','crda','More']].map(([r,i,l])=>`<button class="${active===r?'active':''}" onclick="go('${r}')">${icon(i)}<span>${l}</span></button>`).join('')}};
render=function(){header();const extra={firm:firmPage,firmAuth:authPage,firmSettings:settingsPage,firmMore:morePage,leads:leadsPage,leadEdit:leadEditor,visits:visitsPage,visitEdit:visitEditor,team:teamPage,branches:branchesPage,reports:reportsPage,activity:activityPage,firmPassword:passwordPage};if(extra[route]){try{extra[route]()}catch(e){console.error(e);$('app').innerHTML=empty('Workspace unavailable','Refresh your connection and try again.')}return}original.render();if(enterprise()&&!$('app').querySelector('.firmstrip'))$('app').insertAdjacentHTML('afterbegin',statusStrip())};
home=function(){if(!enterprise()){original.home();return}const rows=filterListings().filter(p=>(!view.mine||p.assignedTo===Firm.data.user.id)&&(!Firm.branchFilter||p.branchId===Firm.branchFilter));$('app').innerHTML=`${statusStrip()}<div class="row sectionhead"><div><div class="eyebrow">SHARED PROPERTY INVENTORY</div><h1>${esc(Firm.data.firm.name)}</h1></div>${writable()?'<button class="btn" onclick="go(\'edit\')">+ Property</button>':''}</div><form class="searchline" onsubmit="event.preventDefault();setFilter('q',this.q.value)"><input name="q" value="${esc(view.q)}" placeholder="Property, village, survey or plot code"><button class="btn" aria-label="Search">${icon('search')}</button></form><div class="chips">${['All','Plot','Apartment','House','Commercial','Farm land'].map(x=>`<button class="chip ${view.type===x?'active':''}" onclick="setFilter('type','${x}')">${x}</button>`).join('')}</div><div class="grid"><select aria-label="Branch filter" onchange="Firm.branchFilter=this.value;home()"><option value="">All branches</option>${Firm.data.branches.map(b=>`<option value="${b.id}" ${Firm.branchFilter===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><select aria-label="Purpose filter" onchange="setFilter('purpose',this.value)">${options(['All','Sale','Rent'],view.purpose)}</select></div><p class="tabnote">${rows.length} visible records. ${role()==='agent'?'Only properties assigned to you.':role()==='viewer'?'Read-only property access; buyer contacts are hidden.':'Managers can assign inventory and branch ownership.'}</p><div class="cards">${rows.map(card).join('')||empty('No assigned properties','Add inventory or ask your manager to assign a property.')}</div><p class="footertext">${Firm.mode==='demo'?'Fictional firm demo stored on this device.':'Shared inventory uses your configured firm backend. The sync view is capped at 1,000 records per entity.'}</p>`};
const originalFilter=filterListings;filterListings=function(){if(!enterprise())return originalFilter();return state.listings.filter(p=>(view.type==='All'||p.type===view.type)&&(view.purpose==='All'||p.purpose===view.purpose)&&(!view.max||p.price<=Number(view.max))&&(!view.q||[p.title,p.village,p.city,p.plotCode,p.survey].join(' ').toLowerCase().includes(view.q.toLowerCase())))};
detail=function(){original.detail();if(!enterprise())return;const p=state.listings.find(x=>x.id===args.id);if(!p)return;if(Firm.mode==='live'&&p.hasPhoto&&!p.photo){firmCall('GET','/api/properties/'+p.id+'/photo').then(r=>{p.photo=r.photo;p.hasPhoto=!!r.photo;if(route==='detail'&&args.id===p.id)detail()}).catch(e=>toast('Property photo unavailable'))}const user=Firm.data.users.find(x=>x.id===p.assignedTo),branch=Firm.data.branches.find(x=>x.id===p.branchId);$('app').insertAdjacentHTML('beforeend',`<div class="panel"><h2>Firm assignment</h2><div class="facts">${fact('Assigned staff',user?.name)}${fact('Branch',branch?.name)}${fact('Record version',p.version||1)}${fact('Workspace',Firm.data.firm.name)}</div>${writable()?`<button class="btn full" style="margin-top:12px" onclick="go('leadEdit',{propertyId:'${p.id}'})">Add buyer enquiry for this property</button>`:''}</div>`);if(!writable())$('app').querySelectorAll('button[onclick^="go(\'edit\'"]').forEach(b=>b.remove());$('app').querySelectorAll('.notice.blue').forEach(n=>{if(n.textContent.includes('Device-local'))n.textContent='Shared firm listing. Property facts remain seller supplied and are not title certification.'})};
edit=function(){if(enterprise()&&!writable()){toast('Your role has read-only property access');go('home');return}original.edit();if(!enterprise())return;const p=state.listings.find(x=>x.id===args.id);Firm.editVersion=p?.version||null;Firm.editSnapshot=p?JSON.parse(JSON.stringify(p)):null;const form=$('propertyForm');form.insertAdjacentHTML('afterbegin',`<div class="panel"><h2>Firm assignment</h2>${staffSelect('Assigned staff','assignedTo',p?.assignedTo||Firm.data.user.id,!manager())}${branchSelect(p?.branchId||'',!manager())}<small>Assignment controls are enforced by the server in connected mode.</small></div>`);form.querySelector('button[type="submit"]').textContent='Save shared property';form.querySelectorAll('button').forEach(b=>{if(b.textContent.includes('Delete this local')){b.textContent='Delete shared property';if(!manager())b.remove()}});$('app').querySelector('.notice.blue').textContent=Firm.mode==='demo'?'Offline demo. Changes affect only the fictional workspace on this device.':'Changes save to your firm server. Version conflicts prevent overwriting another staff member’s edit.'};
function staffSelect(label,name,value,disabled=false){return `<label>${label}</label><select name="${name}" ${disabled?'disabled':''}>${Firm.data.users.filter(u=>u.active&&u.role!=='viewer').map(u=>`<option value="${u.id}" ${u.id===value?'selected':''}>${esc(u.name)} • ${u.role}</option>`).join('')}</select>`}
function branchSelect(value,disabled=false){return `<label>Branch</label><select name="branchId" ${disabled?'disabled':''}><option value="">Unassigned branch</option>${Firm.data.branches.map(b=>`<option value="${b.id}" ${b.id===value?'selected':''}>${esc(b.name)}</option>`).join('')}</select>`}
saveProperty=async function(e){if(!enterprise())return original.saveProperty(e);e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));for(const k of ['price','area','lat','lon','road','bhk'])d[k]=num(d[k]);d.photo=photoDraft;if(Firm.editSnapshot?.hasPhoto&&!photoDraft)delete d.photo;d.plotCode=canonical(d.plotCode);d.assignedTo=d.assignedTo||Firm.editSnapshot?.assignedTo||Firm.data.user.id;d.branchId=d.branchId===undefined?(Firm.editSnapshot?.branchId||null):(d.branchId||null);if(Firm.editVersion)d.version=Firm.editVersion;const result=await firmAction(Firm.editVersion?'PATCH':'POST',Firm.editVersion?'/api/properties/'+args.id:'/api/properties',d);toast('Shared property saved');go('detail',{id:result.id})}catch(e){toast(e.message)}finally{button.disabled=false}};
deleteProperty=async function(id){if(!enterprise())return original.deleteProperty(id);if(!confirm('Delete this shared property for the firm? Existing lead history remains.'))return;try{await firmAction('DELETE','/api/properties/'+id,{version:Firm.editVersion});go('home');toast('Shared property deleted')}catch(e){toast(e.message)}};
function freshDemo(){const users=[{id:'do',name:'Ravi Kumar',email:'owner@example.invalid',role:'owner'},{id:'dm',name:'Saira Rao',email:'manager@example.invalid',role:'manager'},{id:'da',name:'Harish Reddy',email:'agent@example.invalid',role:'agent'},{id:'db',name:'Anusha Devi',email:'agent2@example.invalid',role:'agent'},{id:'dv',name:'Viewer account',email:'viewer@example.invalid',role:'viewer'}].map(x=>({...x,firm_id:'df',active:1}));const properties=DEMOS.map((p,i)=>({...p,id:'dp'+i,assignedTo:i%2?'db':'da',branchId:i%2?'b2':'b1',version:1}));const leads=[{id:'dl1',property_id:'dp0',assigned_to:'da',name:'DEMO • Lakshmi',phone:'',stage:'New',source:'Walk-in',note:'Fictional enquiry; request documents before a site visit.',followup:new Date(Date.now()-3600000).toISOString(),version:1},{id:'dl2',property_id:'dp1',assigned_to:'db',name:'DEMO • Suresh',phone:'',stage:'Visit planned',source:'Referral',note:'Fictional buyer. Discuss suitable inspection time.',followup:null,version:1}];return {firm:{id:'df',name:'Amaravati Realty • DEMO'},user:users[0],users,properties,leads,visits:[{id:'dvisit1',lead_id:'dl2',assigned_to:'db',scheduled:new Date(Date.now()+86400000).toISOString(),status:'Proposed',note:'Fictional visit proposal; buyer confirmation not yet recorded.',version:1}],branches:[{id:'b1',name:'Amaravati Office'},{id:'b2',name:'Vijayawada Office'}],audit:[]}}
function startDemo(){restoreLocal();let d;try{d=JSON.parse(localStorage.getItem('firm_demo_300'))}catch(e){}Firm.data=d?.users?d:freshDemo();Firm.data.user=Firm.data.users.find(u=>u.id===Firm.demoUser)||Firm.data.users[0];Firm.mode='demo';Firm.token='';loadPrivate();useFirmView();go('firm')}
function saveDemo(){localStorage.setItem('firm_demo_300',JSON.stringify(Firm.data))}
function demoRole(id){Firm.demoUser=id;Firm.data.user=Firm.data.users.find(u=>u.id===id);useFirmView();loadPrivate();render()}
function demoAudit(action,id){Firm.data.audit.unshift({id:uid('audit'),actor_id:Firm.data.user.id,action,entity_id:id,created:new Date().toISOString()});Firm.data.audit=Firm.data.audit.slice(0,100)}
async function firmAction(method,path,data){if(Firm.mode==='demo'){const r=demoAction(method,path,data);saveDemo();useFirmView();return r}const sig=method+path+JSON.stringify(data);let key=Firm.retries.get(sig)||uid('op');Firm.retries.set(sig,key);try{const r=await firmCall(method,path,data,key);Firm.retries.delete(sig);await firmRefresh(false);return r}catch(e){if(e.status===409)await firmRefresh(false);throw e}}
function demoAction(m,path,d){const D=Firm.data;if(!writable())throw Error('Read-only role');let id=path.split('/').pop();if(path==='/api/properties'&&m==='POST'){const p={...d,id:uid('dp'),version:1,demo:true};D.properties.unshift(p);demoAudit('property.created',p.id);return p}if(path.startsWith('/api/properties/')){let p=D.properties.find(x=>x.id===id);if(!p)throw Error('Property unavailable');if(role()==='agent'&&p.assignedTo!==D.user.id)throw Error('Property not assigned to you');if(d.version!==p.version)throw Error('Record changed. Refresh before editing.');if(m==='DELETE'){if(!manager())throw Error('Manager access required');D.properties=D.properties.filter(x=>x.id!==id)}else{if(!manager()&&d.assignedTo!==p.assignedTo)throw Error('Manager access required');Object.assign(p,d,{version:p.version+1,demo:true})}demoAudit('property.updated',id);return {id}}if(path==='/api/branches'){if(!manager())throw Error('Manager access required');let b={id:uid('b'),name:d.name};D.branches.push(b);demoAudit('branch.created',b.id);return b}if(path==='/api/leads'){let l={id:uid('dl'),property_id:d.propertyId,assigned_to:d.assignedTo,name:d.name,phone:d.phone,stage:'New',source:d.source,note:d.note,followup:d.followup,version:1};D.leads.unshift(l);demoAudit('lead.created',l.id);return l}if(path.startsWith('/api/leads/')){let l=D.leads.find(x=>x.id===id);if(role()==='agent'&&l.assigned_to!==D.user.id)throw Error('Lead not assigned to you');if(l.version!==d.version)throw Error('Record changed');Object.assign(l,d,{assigned_to:d.assignedTo||l.assigned_to,version:l.version+1});demoAudit('lead.updated',id);return l}if(path==='/api/visits'){let l=D.leads.find(x=>x.id===d.leadId);let v={id:uid('visit'),lead_id:l.id,assigned_to:l.assigned_to,scheduled:d.scheduled,note:d.note,status:'Proposed',version:1};D.visits.unshift(v);demoAudit('visit.proposed',v.id);return v}if(path.startsWith('/api/visits/')){let v=D.visits.find(x=>x.id===id);if(role()==='agent'&&v.assigned_to!==D.user.id)throw Error('Visit not assigned to you');if(v.version!==d.version)throw Error('Record changed');Object.assign(v,d,{version:v.version+1});demoAudit('visit.updated',id);return v}if(path==='/api/invites'){if(role()!=='owner')throw Error('Owner access required');return {inviteCode:'DEMO-ONLY-'+uid(''),email:d.email,role:d.role,expiresInHours:72}}if(path.startsWith('/api/users/')){if(role()!=='owner')throw Error('Owner access required');let u=D.users.find(x=>x.id===id);if(u.role==='owner')throw Error('Cannot change owner');Object.assign(u,d);demoAudit('team.access_changed',id);return {ok:true}}throw Error('Demo operation unavailable')}
function visibleLeads(){if(!enterprise()||role()==='viewer')return [];return Firm.data.leads.filter(l=>role()!=='agent'||l.assigned_to===Firm.data.user.id)}
function visibleVisits(){if(!enterprise()||role()==='viewer')return [];return Firm.data.visits.filter(v=>role()!=='agent'||v.assigned_to===Firm.data.user.id)}
function firmPage(){if(!enterprise()){welcomePage();return}const leads=visibleLeads(),visits=visibleVisits(),due=leads.filter(l=>l.followup&&new Date(l.followup)<new Date()&&!['Won','Lost'].includes(l.stage));$('app').innerHTML=`${statusStrip()}<div class="hero firmhero"><div class="eyebrow">REAL ESTATE FIRM WORKSPACE</div><h1>${esc(Firm.data.firm.name)}</h1><p>${esc(Firm.data.user.name)} • ${role()}. Shared property operations with clear staff responsibility.</p><button class="btn" onclick="${Firm.mode==='demo'?'render()':'firmRefresh()'}">${Firm.mode==='demo'?'View demo overview':'Refresh shared records'}</button></div>${Firm.mode==='demo'?`<div class="panel"><label>Preview staff access (demo only)</label><select onchange="demoRole(this.value)">${Firm.data.users.map(u=>`<option value="${u.id}" ${u.id===Firm.data.user.id?'selected':''}>${esc(u.name)} • ${u.role}</option>`).join('')}</select><small>This selector simulates roles on one device. Live roles come only from the authenticated server.</small></div>`:''}<div class="grid"><div class="stat"><div class="pillcount">${state.listings.length}</div><small>visible properties</small></div><div class="stat"><div class="pillcount">${leads.length}</div><small>buyer enquiries</small></div><div class="stat"><div class="pillcount">${due.length}</div><small>follow-ups due</small></div><div class="stat"><div class="pillcount">${visits.filter(v=>['Proposed','Confirmed'].includes(v.status)).length}</div><small>upcoming visit plans</small></div></div><div class="row sectionhead"><h2>Workspace actions</h2></div><div class="actiongrid">${[['home','home','Property inventory'],['leads','legal','Enquiries & pipeline'],['visits','pin','Site visits'],['crda','crda','CRDA plot import'],['map','map','Property map'],['reports','saved','Firm reports']].map(([r,i,l])=>`<button class="actiontile" onclick="go('${r}')">${icon(i)}<strong>${l}</strong></button>`).join('')}</div><div class="panel" style="margin-top:17px"><h2>Follow-ups due</h2>${due.slice(0,8).map(l=>leadRow(l)).join('')||'<p class="muted">No pending overdue follow-ups in your visible records.</p>'}</div><div class="notice blue">${Firm.mode==='demo'?'Offline demo changes do not create real staff accounts. Connect a deployed backend for independent sign-in on other devices.':'Your permissions are enforced on the server. Private legal checklists and imported CRDA references remain device-local.'}</div>`}
function welcomePage(){$('app').innerHTML=`<div class="hero firmhero"><div class="eyebrow">AGENT MART FIRMS • 3.1</div><h1>One firm.<br>One shared property workspace.</h1><p>Give every agent the right inventory, enquiry ownership and follow-up visibility.</p><button class="btn" style="background:#edb76f;color:#7c2d12" onclick="go('firmSettings')">Connect your firm backend</button></div><div class="grid"><div class="stat"><div class="pillcount">4 roles</div><small>Owner • Manager • Agent • Viewer</small></div><div class="stat"><div class="pillcount">Team access</div><small>Independent staff sign-in</small></div></div><div class="panel" style="margin-top:17px"><h2>Explore the firm version</h2><p class="muted">Preview branches, property assignments, enquiry stages, follow-ups, site visits and reports with fictional records.</p><button class="btn full" onclick="startDemo()">Open offline firm demo</button></div><div class="panel"><h3>Connect for real multi-user access</h3><p class="mini muted">Deploy the included backend on an HTTPS server, enter its address, then create a firm account. The owner issues staff invitations; each staff member signs in independently on their phone.</p><div class="row"><button class="btn secondary grow" onclick="go('firmAuth',{mode:'login'})">Sign in</button><button class="btn outline grow" onclick="go('firmAuth',{mode:'register'})">Create firm</button></div></div><button class="btn outline full" onclick="exitFirm(false)">Continue with local property tools</button><p class="footertext">No live backend is preconfigured. Offline demo users are not real accounts.</p>`}
function settingsPage(){$('app').innerHTML=`${backbtn()}<div class="eyebrow">SHARED SERVER CONNECTION</div><h1>Connect firm backend</h1><div class="panel"><h3>Your HTTPS API origin</h3><p class="mini muted">Use the deployed server supplied by your developer. Example: https://api.yourfirm.in</p><form onsubmit="saveEndpoint(event)"><label for="endpoint">Backend URL</label><input id="endpoint" name="endpoint" type="url" required value="${esc(Firm.endpoint)}" placeholder="https://api.yourfirm.in"><div class="space"></div><button class="btn full">Save connection & test server</button></form><div id="connectionResult" class="tabnote"></div></div><div class="notice blue">The APK sends credentials only to the HTTPS origin you configure. Switching servers signs you out. There is no default owner password.</div><div class="panel"><h3>Server deployment</h3><p class="mini">The developer package includes the Python API, SQLite schema initialization, Docker deployment, HTTPS gateway configuration, authorization tests and operating notes. A server hostname and hosting account are required to run it across devices.</p></div>`}
async function saveEndpoint(e){e.preventDefault();try{const u=new URL(e.target.endpoint.value.trim());if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('Enter only an HTTPS origin, with no path or credentials.');const origin=u.origin;if(window.AndroidApp?.configureBackend&&!AndroidApp.configureBackend(origin))throw Error('Android rejected this backend URL.');if(Firm.token)await exitFirm(false);Firm.endpoint=origin;localStorage.setItem('firm_endpoint_300',origin);const r=await firmCall('GET','/api/health');if(r.service!=='Agent Mart Firms')throw Error('This is not an Agent Mart Firms backend.');$('connectionResult').textContent='Connected to Agent Mart Firms '+r.version;toast('Backend connection verified');go('firmAuth',{mode:'login'})}catch(e){$('connectionResult')&&($('connectionResult').textContent=e.message);toast(e.message)}}
function authPage(){const mode=args.mode||'login';$('app').innerHTML=`${backbtn()}<div class="eyebrow">${mode==='register'?'OWNER ACCOUNT':mode==='join'?'STAFF INVITATION':'SECURE FIRM SIGN-IN'}</div><h1>${mode==='register'?'Create your firm':mode==='join'?'Join your firm':'Sign in to your firm'}</h1><div class="chips">${[['login','Sign in'],['register','Create firm'],['join','Join invitation']].map(([x,l])=>`<button class="chip ${x===mode?'active':''}" onclick="args.mode='${x}';authPage()">${l}</button>`).join('')}</div><div class="notice blue">${Firm.endpoint?esc(Firm.endpoint):'Set your HTTPS backend URL before creating accounts.'}</div><form class="panel" onsubmit="authenticate(event,'${mode}')">${mode==='register'?input('Firm / company name','firmName','','text',true):''}${mode!=='login'?input('Your name','name','','text',true):''}${input('Email address','email','','email',true)}${input('Password (minimum 10 characters)','password','','password',true,'minlength="10" maxlength="200" autocomplete="'+(mode==='login'?'current-password':'new-password')+'"')}${mode==='join'?input('Invitation code','inviteCode','','text',true):''}<div class="space"></div><button class="btn full" type="submit">${mode==='login'?'Sign in':mode==='register'?'Create firm & owner account':'Accept invitation'}</button></form><button class="btn outline full" onclick="go('firmSettings')">Change backend connection</button><p class="footertext">Staff invitations are tied to the exact email address and expire in 72 hours. No email is sent automatically. Share the invitation code directly with the intended staff member.</p>`}
async function authenticate(e,mode){e.preventDefault();const btn=e.target.querySelector('button[type="submit"]');btn.disabled=true;try{const connectionOrigin=Firm.endpoint,d=Object.fromEntries(new FormData(e.target)),r=await firmCall('POST','/api/auth/'+(mode==='register'?'register':mode==='join'?'join':'login'),d);if(Firm.endpoint!==connectionOrigin)throw Error('Backend changed during sign-in. Sign in again.');Firm.token=r.token;Firm.mode='live';Firm.data={user:r.user};restoreLocal();loadPrivate();await firmRefresh(false);if(!Firm.data?.firm)throw Error('Signed in, but unable to load workspace. Retry refresh.');route='firm';args={};stack=[];render();toast('Signed in to your firm')}catch(e){toast(e.message)}finally{btn.disabled=false}}
async function exitFirm(navigate=true){if(Firm.token){try{await firmCall('POST','/api/auth/logout')}catch(e){}}Firm.token='';Firm.data=null;Firm.mode='local';Firm.editVersion=null;Firm.branchFilter='';Firm.retries.clear();restoreLocal();view={q:'',type:'All',purpose:'All',mine:false,max:''};route=navigate?'firm':'home';args={};stack=[];render()}
function morePage(){$('app').innerHTML=`${statusStrip()}<h1>Firm tools</h1><div class="panel linklist">${[['team','Team & roles'],['branches','Branches'],['reports','Firm reports'],['activity','Activity history'],['crda','CRDA plot references'],['map','Property map'],['legal','Legal search portals'],['saved','Saved properties'],['firmSettings','Backend connection'],['firmPassword','Change password'],['about','Source information']].filter(([r])=>!['activity'].includes(r)||manager()).map(([r,l])=>`<a href="#" onclick="event.preventDefault();go('${r}')">${l} →</a>`).join('')}</div><button class="btn danger full" onclick="exitFirm()">${Firm.mode==='demo'?'Exit offline demo':'Sign out & clear shared session'}</button><p class="footertext">${Firm.mode==='live'?'Sessions expire after 12 hours. Passwords and tokens are not saved in device storage.':'Demo data remains on this device for your next preview.'}</p>`}
function leadRow(l){const p=Firm.data.properties.find(p=>p.id===l.property_id),u=Firm.data.users.find(u=>u.id===l.assigned_to);return `<div class="listrow" onclick="go('leadEdit',{id:'${l.id}'})"><div class="row"><strong>${esc(l.name)}</strong><span class="tag">${esc(l.stage)}</span></div><small>${esc(p?.title||'Property removed')} • ${esc(u?.name||'Unassigned')}</small><small>${l.followup?'Follow-up: '+new Date(l.followup).toLocaleString('en-IN'):'No follow-up scheduled'}</small></div>`}
function leadsPage(){if(!enterprise())return welcomePage();if(role()==='viewer'){$('app').innerHTML=empty('Buyer contacts are restricted','Your viewer role can browse property inventory and property reports.');return}const stage=args.stage||'All',rows=visibleLeads().filter(l=>stage==='All'||l.stage===stage);$('app').innerHTML=`${statusStrip()}<div class="row sectionhead"><div><div class="eyebrow">BUYER ENQUIRIES & FOLLOW-UPS</div><h1>Firm pipeline</h1></div><button class="btn" onclick="go('leadEdit')">+ Enquiry</button></div><div class="chips">${['All',...['New','Contacted','Qualified','Visit planned','Negotiation','Won','Lost']].map(x=>`<button class="chip ${stage===x?'active':''}" onclick="args.stage='${x}';leadsPage()">${x}</button>`).join('')}</div><div class="panel">${rows.map(leadRow).join('')||'<p class="muted">No enquiries in this stage.</p>'}</div><p class="footertext">Enquiries are entered by authorized staff. Public website enquiry intake and WhatsApp message ingestion are not connected.</p>`}
function localDatetime(s){if(!s)return '';const d=new Date(s);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function leadEditor(){if(!enterprise()||!writable())return leadsPage();const l=visibleLeads().find(l=>l.id===args.id),pId=l?.property_id||args.propertyId||state.listings[0]?.id||'',assigned=l?.assigned_to||state.listings.find(p=>p.id===pId)?.assignedTo||Firm.data.user.id;Firm.leadVersion=l?.version; $('app').innerHTML=`${backbtn()}${statusStrip()}<h1>${l?'Manage enquiry':'New buyer enquiry'}</h1><form class="panel" onsubmit="saveLead(event,'${l?.id||''}')"><label>Property *</label><select name="propertyId" ${l?'disabled':''}>${state.listings.map(p=>`<option value="${p.id}" ${p.id===pId?'selected':''}>${esc(p.title)}</option>`).join('')}</select>${!l?input('Buyer name','name','','text',true)+input('Buyer mobile','phone','','tel',true,'pattern="[6-9][0-9]{9}" maxlength="10"'):`<div class="facts">${fact('Buyer',l.name)}${fact('Mobile',l.phone||'Fictional demo contact')}</div><label>Lead stage</label><select name="stage">${options(['New','Contacted','Qualified','Visit planned','Negotiation','Won','Lost'],l.stage)}</select>`}${staffSelect('Assigned staff','assignedTo',assigned,!manager())}${!l?select('Source','source',['Manual','Phone call','Referral','Walk-in','Website','WhatsApp'],'Manual'):''}<label>Next follow-up</label><input name="followup" type="datetime-local" value="${localDatetime(l?.followup)}"><label>Internal notes</label><textarea name="note" maxlength="2500">${esc(l?.note||'')}</textarea>${!l?'<div class="checkrow" style="margin-top:15px"><input id="contactConsent" name="contactConsent" type="checkbox" required><label for="contactConsent">I have permission to store and share this buyer contact within this firm for this enquiry.</label></div>':''}<div class="space"></div><button class="btn full" type="submit">Save enquiry</button>${l?`<button class="btn secondary full" type="button" style="margin-top:9px" onclick="go('visitEdit',{leadId:'${l.id}'})">Schedule site visit</button>`:''}</form>`}
async function saveLead(e,id){e.preventDefault();let b=e.target.querySelector('button[type="submit"]');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.followup=d.followup?new Date(d.followup).toISOString():null;d.assignedTo=d.assignedTo||Firm.data.user.id;if(!id)d.contactConsent=$('contactConsent').checked;else d.version=Firm.leadVersion;await firmAction(id?'PATCH':'POST',id?'/api/leads/'+id:'/api/leads',d);go('leads');toast('Enquiry saved')}catch(e){toast(e.message)}finally{b.disabled=false}}
function visitsPage(){if(!enterprise()||role()==='viewer'){$('app').innerHTML=empty('Visits are restricted','Ask the owner for an appropriate staff role.');return}const rows=visibleVisits();$('app').innerHTML=`${statusStrip()}<div class="row sectionhead"><div><div class="eyebrow">SITE VISIT PLANNER</div><h1>Visits & inspections</h1></div><button class="btn" onclick="go('visitEdit')">+ Visit</button></div><div class="panel">${rows.map(v=>{const l=Firm.data.leads.find(l=>l.id===v.lead_id);return `<div class="listrow" onclick="go('visitEdit',{id:'${v.id}'})"><div class="row"><strong>${esc(l?.name||'Buyer enquiry')}</strong><span class="tag">${esc(v.status)}</span></div><small>${new Date(v.scheduled).toLocaleString('en-IN')}</small><small>${esc(v.note)}</small></div>`}).join('')||'<p class="muted">No visits scheduled.</p>'}</div><div class="notice blue">Staff records proposed and buyer-confirmed visits manually. A proposal is not automatic buyer confirmation. Rescheduling returns the plan to Proposed.</div>`}
function visitEditor(){if(!writable())return visitsPage();const v=visibleVisits().find(x=>x.id===args.id),leads=visibleLeads();Firm.visitVersion=v?.version;$('app').innerHTML=`${backbtn()}${statusStrip()}<h1>${v?'Update site visit':'Schedule a site visit'}</h1><form class="panel" onsubmit="saveVisit(event,'${v?.id||''}')"><label>Buyer enquiry</label><select name="leadId" ${v?'disabled':''}>${leads.map(l=>`<option value="${l.id}" ${l.id===(v?.lead_id||args.leadId)?'selected':''}>${esc(l.name)}</option>`).join('')}</select><label>Visit date and time *</label><input name="scheduled" type="datetime-local" required value="${localDatetime(v?.scheduled)}">${v?select('Recorded visit status','status',['Proposed','Confirmed','Completed','Cancelled','No-show'],v.status):''}<label>Meeting point / notes</label><textarea name="note" maxlength="1500">${esc(v?.note||'')}</textarea><div class="space"></div><button class="btn full" ${!leads.length?'disabled':''}>Save visit</button></form><div class="notice">Confirmed means a staff member has recorded the buyer’s agreement. This app does not automatically obtain that agreement.</div>`}
async function saveVisit(e,id){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.scheduled=new Date(d.scheduled).toISOString();if(id)d.version=Firm.visitVersion;await firmAction(id?'PATCH':'POST',id?'/api/visits/'+id:'/api/visits',d);go('visits');toast('Visit saved')}catch(e){toast(e.message)}finally{b.disabled=false}}
function teamPage(){if(!enterprise())return welcomePage();$('app').innerHTML=`${backbtn()}${statusStrip()}<h1>Team & access</h1><div class="panel">${Firm.data.users.map(u=>`<div class="listrow"><div class="row"><div><strong>${esc(u.name)}</strong><small>${esc(u.email||'')} • ${esc(u.role)} • ${u.active?'Active':'Disabled'}</small></div>${role()==='owner'&&u.role!=='owner'?`<button class="btn ${u.active?'outline':'secondary'}" onclick="changeAccess('${u.id}',${u.active?0:1})">${u.active?'Disable':'Enable'}</button>`:''}</div>${role()==='owner'&&u.role!=='owner'?`<select aria-label="Role for ${esc(u.name)}" onchange="changeRole('${u.id}',this.value)">${options(['manager','agent','viewer'],u.role)}</select>`:''}</div>`).join('')}</div>${role()==='owner'?`<form class="panel" onsubmit="inviteStaff(event)"><h2>Invite staff member</h2>${input('Staff email','email','','email',true)}${select('Role','role',['manager','agent','viewer'],'agent')}<div class="space"></div><button class="btn full">Generate invitation code</button><div id="inviteResult"></div></form>`:'<div class="notice blue">Only the firm owner can invite, disable or change staff roles.</div>'}<details><summary>Permission guide</summary><p class="mini">Owner: full firm access and team administration.<br>Manager: firm inventory, branches, assignment, enquiries, visits and reports.<br>Agent: assigned properties, own assigned enquiries and visits; no staff administration.<br>Viewer: read-only property inventory; buyer contact records are hidden.</p></details>`}
async function inviteStaff(e){e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),r=await firmAction('POST','/api/invites',d);$('inviteResult').innerHTML=`<div class="notice ${Firm.mode==='demo'?'':'blue'}">${Firm.mode==='demo'?'DEMO CODE - cannot create real accounts.':'Share this one-time code with '+esc(r.email)+'. It expires in 72 hours.'}</div><textarea readonly>${esc(r.inviteCode)}</textarea><small>The code is shown only in this response. No email is sent automatically.</small>`}catch(e){toast(e.message)}}
async function changeAccess(id,active){if(!confirm((active?'Enable':'Disable')+' this staff account? Active sessions will be revoked.'))return;try{await firmAction('PATCH','/api/users/'+id,{active});render();toast('Staff access updated')}catch(e){toast(e.message)}}
async function changeRole(id,role){try{await firmAction('PATCH','/api/users/'+id,{role});render();toast('Role changed; staff must sign in again')}catch(e){toast(e.message)}}
function branchesPage(){$('app').innerHTML=`${backbtn()}${statusStrip()}<h1>Firm branches</h1><div class="panel">${Firm.data.branches.map(b=>`<div class="listrow"><strong>${esc(b.name)}</strong><small>${Firm.data.properties.filter(p=>p.branchId===b.id).length} visible properties</small></div>`).join('')||'<p class="muted">No branches created.</p>'}</div>${manager()?`<form class="panel" onsubmit="addBranch(event)"><h3>Add branch</h3>${input('Branch name','name','','text',true)}<div class="space"></div><button class="btn full">Create branch</button></form>`:''}`}
async function addBranch(e){e.preventDefault();try{await firmAction('POST','/api/branches',{name:e.target.elements.namedItem('name').value});render();toast('Branch added')}catch(e){toast(e.message)}}
function reportsPage(){const leads=visibleLeads(),props=state.listings,visits=visibleVisits(),stages=['New','Contacted','Qualified','Visit planned','Negotiation','Won','Lost'];$('app').innerHTML=`${backbtn()}${statusStrip()}<div class="eyebrow">WORKSPACE PERFORMANCE</div><h1>Firm reports</h1><div class="grid"><div class="stat"><div class="pillcount">${props.length}</div><small>visible properties</small></div><div class="stat"><div class="pillcount">${props.filter(p=>p.status==='Available').length}</div><small>available properties</small></div><div class="stat"><div class="pillcount">${leads.length}</div><small>visible enquiries</small></div><div class="stat"><div class="pillcount">${visits.filter(v=>v.status==='Completed').length}</div><small>completed visits</small></div></div><div class="panel" style="margin-top:17px"><h2>Enquiry stages</h2>${stages.map(s=>{const n=leads.filter(l=>l.stage===s).length;return `<div class="reportrow"><span>${s}</span><div class="reportbar"><i style="width:${leads.length?n/leads.length*100:0}%"></i></div><b>${n}</b></div>`}).join('')}</div><div class="panel"><h2>Property availability</h2>${['Draft','Available','On hold','Sold','Rented'].map(s=>`<div class="row fact"><span>${s}</span><b>${props.filter(p=>p.status===s).length}</b></div>`).join('')}</div><div class="notice blue">Counts reflect records visible to your role, capped at the current sync limit. Won is a staff-recorded lead stage, not proof of a completed registered sale.</div><button class="btn outline full" onclick="exportReport()">Share summary CSV</button>`}
function exportReport(){const rows=[['metric','count'],['visible_properties',state.listings.length],['available_properties',state.listings.filter(p=>p.status==='Available').length],['visible_enquiries',visibleLeads().length],['completed_visits',visibleVisits().filter(v=>v.status==='Completed').length]];shareText('Agent Mart firm summary',rows.map(r=>r.join(',')).join('\n'))}
function activityPage(){if(!manager()){$('app').innerHTML=empty('Manager access required','Activity history is restricted.');return}$('app').innerHTML=`${backbtn()}${statusStrip()}<h1>Activity history</h1><div class="panel">${Firm.data.audit.map(a=>`<div class="history"><strong>${esc(a.action)}</strong><br>${esc(Firm.data.users.find(u=>u.id===a.actor_id)?.name||'Staff member')}<br><small>${new Date(a.created).toLocaleString('en-IN')} • ${esc(a.entity_id)}</small></div>`).join('')||'<p class="muted">No activity history yet.</p>'}</div><p class="footertext">Latest 100 activity events are shown. Audit entries cannot be edited from the app.</p>`}
if(Firm.endpoint&&window.AndroidApp?.configureBackend)AndroidApp.configureBackend(Firm.endpoint);
