const originalAbout=aboutPage;
aboutPage=function(){originalAbout();$('app').querySelector('.eyebrow').textContent='AGENT MART FIRMS • 3.1';const first=$('app').querySelector('.panel');if(first)first.innerHTML='<h3>Property and firm workspace</h3><p>Local property tools plus a firm dashboard, four staff roles, branches, assignments, enquiries, follow-ups, visits and reports.</p><p class="mini muted">Live multi-user mode requires the supplied backend to be deployed on your HTTPS server. Offline demo roles do not create shared accounts. CRDA reference records and private legal checklists stay device-local.</p>'};

function readLocalProjects(){try{return JSON.parse(localStorage.getItem('insight_projects_310')||'[]')}catch(e){return []}}
// Plot evidence and deterministic investment scenarios are separate calculations.
const Insight={report:null,busy:false,category:'all',question:'',query:'',radius:3000,modelText:'',projects:readLocalProjects(),cache:new Map()};
const Growth={price:5000000,acquisition:0,holding:0,selling:0,inflation:0,rates:[-2,5,8],result:null,label:'Illustrative purchase price; enter your own figure'};
const insightOriginal={render,header,home,detail,refDetail,firmPage,morePage};
header=function(){insightOriginal.header()};
home=function(){insightOriginal.home();$('app').insertAdjacentHTML('afterbegin',`<div class="row" style="margin-bottom:16px"><button class="btn grow" onclick="go('plotAI')">Plot intelligence</button><button class="btn secondary grow" onclick="go('investment')">10-year outlook</button></div>`)};
render=function(){const custom={plotAI:plotAIPage,investment:investmentPage,development:developmentPage};if(custom[route]){header();custom[route]();return}insightOriginal.render()};
firmPage=function(){insightOriginal.firmPage();const hero=$('app').querySelector('.hero');if(hero)hero.insertAdjacentHTML('afterend',`<div class="insightentry"><div><span class="eyebrow">NEW • PLOT INTELLIGENCE</span><h3>Know the plot. Explore the surroundings.</h3><p>Plot-code research, nearby education & services, development evidence and 10-year scenarios.</p></div><div class="row"><button class="btn grow" onclick="go('plotAI')">Search a plot</button><button class="btn secondary grow" onclick="go('investment')">10-year outlook</button></div></div>`)};
morePage=function(){insightOriginal.morePage();$('app').insertAdjacentHTML('afterbegin',`<div class="row" style="margin-bottom:16px"><button class="btn grow" onclick="go('plotAI')">Plot intelligence</button><button class="btn secondary grow" onclick="go('investment')">Investment outlook</button></div>`)};
detail=function(){insightOriginal.detail();const p=state.listings.find(x=>x.id===args.id);if(p)$('app').insertAdjacentHTML('beforeend',`<div class="panel"><h2>Plot insights & investment</h2><p class="muted">Explore nearby places and development evidence, then model your own 10-year assumptions.</p><div class="row"><button class="btn grow" onclick="propertyInsight('${p.id}')">Plot intelligence</button><button class="btn secondary grow" onclick="propertyGrowth('${p.id}')">10-year outlook</button></div></div>`)};
