function propertyInsight(id){const p=state.listings.find(x=>x.id===id);if(p.plotCode)Insight.query=p.plotCode;else Insight.query='';Insight.report=null;go('plotAI');if(!p.plotCode)toast('Enter a CRDA plot code to resolve its official location.')}
function propertyGrowth(id){const p=state.listings.find(x=>x.id===id);Growth.price=p.purpose==='Rent'?5000000:(p.price||5000000);Growth.label=p.purpose==='Rent'?'Rental listing does not supply a purchase price. Enter your purchase assumption.':(p.demo?'Fictional sample asking price: ':'Seller asking price, not verified market value: ')+p.title;go('investment')}
function refInsight(id){const r=state.refs.find(r=>r.id===id);Insight.query=r.code;Insight.report=null;go('plotAI')}
function km(m){return m<1000?Math.round(m)+' m':(m/1000).toFixed(2)+' km'}
function haversine(lat,lon,la,lo){const a=lat*Math.PI/180,b=la*Math.PI/180,d=(la-lat)*Math.PI/180,e=(lo-lon)*Math.PI/180,h=Math.sin(d/2)**2+Math.cos(a)*Math.cos(b)*Math.sin(e/2)**2;return 6371000*2*Math.asin(Math.min(1,Math.sqrt(h)))}
function polyCentre(g){const r=g?.rings?.[0];if(!r?.length)return null;const ps=r.slice(0,-1);if(!ps.length)return null;return {lat:ps.reduce((s,p)=>s+p[1],0)/ps.length,lon:ps.reduce((s,p)=>s+p[0],0)/ps.length}}
function parsePlotRequest(text){const code=canonical((text.match(/\b\d{1,3}-\d{1,4}-\d{1,5}-\d{1,5}-[a-z0-9]{1,8}\b/i)||[])[0]||'');const m=text.match(/\b([135])\s*(?:km|kilomet)/i);let category=/school|పాఠశాల/i.test(text)?'school':/college|university|కాలేజీ|కళాశాల/i.test(text)?'education':/hospital|ఆసుపత్రి/i.test(text)?'health':/bus|rail|transport|బస్/i.test(text)?'transport':'all';return {code,radius:m?+m[1]*1000:Insight.radius,category}}
function plotAIPage(){const R=Insight.report;$('app').innerHTML=`${backbtn()}<div class="hero"><div class="eyebrow">PLOT INTELLIGENCE • SOURCE-LED RESEARCH</div><h1>One plot code.<br>A clearer local picture.</h1><p>Plot facts, nearby places, dated development references and an editable investment outlook.</p></div><form class="panel" onsubmit="runPlotSearch(event)"><label for="plotquery">Ask about a CRDA plot</label><textarea id="plotquery" maxlength="400" rows="2" placeholder="Schools near 13-535-2974-11-C18 within 3 km">${esc(Insight.query)}</textarea><div class="row"><div class="grow"><label>Search radius</label><select id="plotradius">${[1000,3000,5000].map(n=>`<option value="${n}" ${n===Insight.radius?'selected':''}>${n/1000} km</option>`).join('')}</select></div><button class="btn grow" style="align-self:end" ${Insight.busy?'disabled':''}>${Insight.busy?'Checking sources…':'Find plot insights'}</button></div><small>Understands a plot code and basic category/radius words. A language-model narrative is optional and requires your configured firm server.</small></form><div id="insightstatus" class="tabnote">${Insight.busy?'Loading plot identity and nearby evidence. External sources can take time.':''}</div>${R?renderEvidence(R):`<div class="grid"><div class="stat"><strong>Nearby essentials</strong><small style="display:block">Schools, colleges, health & transport</small></div><div class="stat"><strong>10-year scenarios</strong><small style="display:block">Editable growth, costs & inflation</small></div></div><div class="notice blue">No purchase price or appreciation is inferred from a plot code. Market value needs reliable comparable transactions and independent checks.</div><button class="btn outline full" onclick="go('investment')">Open investment scenario calculator</button>`}`;if(R)renderInsightMap()}
async function publicJSON(path,params){const ac=new AbortController(),tm=setTimeout(()=>ac.abort(),40000);try{const res=await fetch(path+'?'+new URLSearchParams(params),{signal:ac.signal});if(!res.ok)throw Error('Source request failed');const d=await res.json();if(d.error)throw Error(d.error.message||'Source unavailable');return d}finally{clearTimeout(tm)}}
async function localEvidence(code,radius){const d=await publicJSON('/crda-query',{where:`UPPER(plot_code)='${code}'`,outFields:FIELDS,returnGeometry:'true',outSR:'4326',f:'json',resultRecordCount:'2'});if(d.features?.length!==1)throw Error('No unique plot match in the official GIS. Check the exact code.');const r=normalize(d.features[0],'CRDA GIS live lookup'),p={code:r.code,village:r.village,district:r.district,mandal:r.mandal,areaSqYd:r.area,roadM:r.road,landUse:r.landUse,zoning:r.zoning,survey:r.survey,lat:r.lat,lon:r.lon,rings:r.rings,source:GIS,vintage:'Layer name refers to Nov 2018; current ownership not established'};if(!coords(p.lat,p.lon))throw Error('Source plot has no usable location');
 const R={plot:p,radius,nearby:{places:[],provider:'Unavailable'},developments:{projects:[]},errors:[],fetchedAt:new Date().toISOString(),distanceMethod:'Approximate straight-line centre-to-centre distance, not road travel distance',modelConfigured:false};
 const q=`[out:json][timeout:18];(nwr(around:${radius},${p.lat},${p.lon})[amenity~"^(school|college|university|hospital|clinic|bus_station|bank)$"];node(around:${radius},${p.lat},${p.lon})[highway=bus_stop];nwr(around:${radius},${p.lat},${p.lon})[railway=station];);out center tags 150;`;
 const outcomes=await Promise.allSettled([publicJSON('/nearby-query',{data:q}),publicJSON('/development-query',{where:'1=1',geometry:p.lon+','+p.lat,geometryType:'esriGeometryPoint',inSR:'4326',spatialRel:'esriSpatialRelIntersects',distance:String(radius),units:'esriSRUnit_Meter',outFields:'FID,Name,Category,Zoning,Theme_City,Area_Ac',returnGeometry:'true',outSR:'4326',f:'json'})]);
 if(outcomes[0].status==='fulfilled'&&!outcomes[0].value.remark){const data=outcomes[0].value;R.nearby={provider:'OpenStreetMap',notice:'Community map entries. Operating status and completeness are unverified.',places:(data.elements||[]).map(x=>{const l=x.center||x,t=x.tags||{},cat=t.amenity||(t.highway==='bus_stop'?'bus_stop':'railway_station');return {id:x.type+'/'+x.id,name:t.name||t['name:en']||t['name:te']||'Unnamed mapped '+cat,category:cat,lat:l.lat,lon:l.lon,distanceM:coords(l.lat,l.lon)?Math.round(haversine(p.lat,p.lon,l.lat,l.lon)):Infinity,source:'OpenStreetMap',url:'https://www.openstreetmap.org/'+x.type+'/'+x.id}}).filter(x=>x.distanceM<=radius).sort((a,b)=>a.distanceM-b.distanceM).slice(0,100)}}else R.errors.push('Nearby map service unavailable or incomplete. This does not mean no amenities exist.');
 if(outcomes[1].status==='fulfilled'){R.developments={source:'https://gis.apcrda.org/server/rest/services/LPS_Portal/MapServer/13',notice:'Historical land allocations as of February 2025; not construction or operational status.',projects:(outcomes[1].value.features||[]).map(f=>{const a=f.attributes||{},c=polyCentre(f.geometry);return c?{id:'crda-'+a.FID,name:a.Name||'Unnamed allocation',category:a.Category||'Allocation',zoning:a.Zoning,lat:c.lat,lon:c.lon,distanceM:Math.round(haversine(p.lat,p.lon,c.lat,c.lon)),sourceDate:'2025-02',status:'Allocation reference; construction/operation unknown',source:'https://gis.apcrda.org/server/rest/services/LPS_Portal/MapServer/13'}:null}).filter(x=>x&&x.distanceM<=radius).sort((a,b)=>a.distanceM-b.distanceM).slice(0,50)}}else R.errors.push('Official development-reference layer unavailable.');return R;
}
async function runPlotSearch(e){e.preventDefault();if(Insight.busy)return;Insight.query=$('plotquery').value.trim();Insight.radius=+$('plotradius').value;const parsed=parsePlotRequest(Insight.query);if(!parsed.code){toast('Include an exact CRDA plot code, for example 13-535-2974-11-C18.');return}Insight.radius=parsed.radius;Insight.category=parsed.category;Insight.modelText='';Insight.busy=true;plotAIPage();try{const key=parsed.code+'|'+Insight.radius,cached=Insight.cache.get(key);let R;if(cached&&Date.now()-cached.at<600000)R=cached.report;else{R=Firm.mode==='live'&&Firm.token?await firmCall('POST','/api/intelligence/search',{plotCode:parsed.code,radius:Insight.radius}):await localEvidence(parsed.code,Insight.radius);if(R.nearby.provider!=='Google Maps')Insight.cache.set(key,{at:Date.now(),report:R})}Insight.report=R;Insight.busy=false;plotAIPage();toast('Plot evidence report ready')}catch(e){Insight.busy=false;plotAIPage();$('insightstatus').textContent=e.message;toast('Unable to complete plot lookup. No data was invented.')}}
function selectedPlaces(){const ps=Insight.report?.nearby?.places||[],cat=Insight.category;return ps.filter(p=>cat==='all'||cat==='school'&&p.category==='school'||cat==='education'&&['college','university'].includes(p.category)||cat==='health'&&['hospital','clinic'].includes(p.category)||cat==='transport'&&['bus_stop','bus_station','train_station','railway_station'].includes(p.category))}
function firmProjects(){const p=Insight.report?.plot;if(!p)return [];const rows=enterprise()?Firm.data.developments||[]:Insight.projects;return rows.map(x=>({...x,distanceM:Math.round(haversine(p.lat,p.lon,x.lat,x.lon))})).filter(x=>x.distanceM<=Insight.radius).sort((a,b)=>a.distanceM-b.distanceM)}
function dataHighlights(R){const p=R.plot,rows=[];rows.push(`${fmt(p.areaSqYd)} sq yd; source land use: ${p.landUse||'not supplied'}.`);if(p.roadM>0)rows.push(`Source road-width field: ${fmt(p.roadM)} metres. Current road condition has not been checked.`);else rows.push('Road-width information is missing or zero; confirm access on site.');const schools=R.nearby.places.filter(x=>x.category==='school'),education=R.nearby.places.filter(x=>['college','university'].includes(x.category));if(R.nearby.provider!=='Unavailable'){rows.push(`${schools.length} school and ${education.length} college/university map entries returned within ${R.radius/1000} km. Results are capped and may be incomplete.`);if(schools[0])rows.push(`Nearest returned school entry: ${schools[0].name}, approximately ${km(schools[0].distanceM)} straight-line.`)}else rows.push('Nearby place coverage could not be checked; do not interpret this as an absence of schools or services.');rows.push(`${R.developments.projects.length} historical allocation references returned nearby; their development and operating status is unknown.`);rows.push('Legal title, comparable transaction prices, access rights, flood/drainage conditions and project progress still require independent verification.');return rows}
function renderEvidence(R){const p=R.plot,ps=selectedPlaces(),fp=firmProjects();return `<div class="refdetail"><span class="tag">OFFICIAL PLOT IDENTITY • NO PRICE FORECAST</span><h1>${esc(p.code)}</h1><p>${esc(p.village)} • ${esc(p.district)}</p><div class="price">${fmt(p.areaSqYd)} <small>sq yd</small></div><small>${esc(p.landUse||'Land use not supplied')}</small></div><div class="panel"><h2>Data-based plot highlights</h2>${R.nearby.provider==='Google Maps'?'<p class="googlecredit" translate="no">Google Maps</p>':''}<ul class="insightlist">${dataHighlights(R).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>Generated from returned fields and explicit rules, not an independent valuation or an AI forecast.</small></div>${R.errors.map(x=>`<div class="notice">${esc(x)}</div>`).join('')}<div id="insightmap" class="map"></div><p class="mini muted">${esc(R.distanceMethod)}. Pins are representative map locations; not road distances or verified entrances. Google Places results are listed separately and are not plotted on this OpenStreetMap base.</p><div class="panel"><h2>Nearby places</h2><div class="chips">${[['all','All'],['school','Schools'],['education','Colleges'],['health','Health'],['transport','Transport']].map(([c,l])=>`<button class="chip ${Insight.category===c?'active':''}" onclick="Insight.category='${c}';plotAIPage()">${l}</button>`).join('')}</div><small>${esc(R.nearby.provider)} • ${esc(R.nearby.notice||'Availability unknown')}</small>${R.nearby.provider==='Google Maps'?'<p class="googlecredit" translate="no">Google Maps</p>':''}${ps.slice(0,30).map(x=>`<div class="placeitem"><div class="row"><strong>${esc(x.name)}</strong><span class="tag">${km(x.distanceM)}</span></div><small>${esc(x.category.replaceAll('_',' '))} • ${esc(x.source)}</small><div class="row"><a href="${esc(x.url)}">Source entry ↗</a><a href="https://www.google.com/maps/dir/?api=1&destination=${x.lat},${x.lon}">Road route ↗</a></div>${(x.attributions||[]).map(a=>`<small>${esc(a.provider||'')}${a.providerUri?' '+esc(a.providerUri):''}</small>`).join('')}</div>`).join('')||'<p class="muted">No matching places were returned. Coverage may be incomplete.</p>'}<div class="row wrap">${['schools','colleges','hospitals'].map(q=>`<a class="btn outline grow" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q+' near '+p.lat+','+p.lon)}">Find ${q} on Maps</a>`).join('')}</div></div><div class="panel"><h2>Nearby development evidence</h2><div class="notice">CRDA layer: February 2025 land allocations. These are not verified upcoming projects, construction progress or operating campuses.</div>${R.developments.projects.slice(0,18).map(x=>`<div class="placeitem"><div class="row"><strong>${esc(x.name)}</strong><span class="tag amber">${km(x.distanceM)}</span></div><small>${esc(x.category)} • ${esc(x.sourceDate)} reference</small><p class="mini">${esc(x.status)}</p><a href="${esc(x.source)}">Official layer metadata ↗</a></div>`).join('')||'<p class="muted">No nearby allocation references returned. This is not evidence that no development exists.</p>'}<h3 style="margin-top:22px">Firm / user sourced project updates</h3>${fp.map(x=>`<div class="placeitem"><strong>${esc(x.title)}</strong><div class="row"><span class="tag">${esc(x.status)}</span><small>${km(x.distanceM)}</small></div><small>User/firm claim; not independently verified. Source date: ${esc(x.sourceDate||'not supplied')}</small><p class="mini">${esc(x.note||'')}</p><a href="${esc(x.sourceUrl)}">Read source evidence ↗</a></div>`).join('')||'<p class="muted">No dated project updates have been added for this area.</p>'}<button class="btn secondary full" onclick="go('development')">Add a sourced development update</button></div><div class="panel"><h2>Optional AI narrative</h2><p class="mini muted">A configured firm AI service can explain the evidence. It does not calculate market value or predict appreciation.</p>${Insight.modelText?`<div class="ainarrative">${esc(Insight.modelText).replace(/\n/g,'<br>')}</div>`:''}<button class="btn outline full" onclick="requestNarrative(this)">Explain these sources with AI</button></div><div class="row wrap"><button class="btn grow" onclick="go('investment')">10-year investment scenarios</button><button class="btn secondary grow" onclick="shareInsights()">Share source summary</button></div><p class="footertext">Checked ${new Date(R.fetchedAt).toLocaleString('en-IN')}. ${esc(p.vintage)}. A refresh date does not verify present ownership, project completion or school quality.</p>`}
function renderInsightMap(){const R=Insight.report,el=$('insightmap');if(!R||!el)return;const p=R.plot,ref={...p,id:'insightPlot',code:p.code};makeMap('insightmap',[],[ref],p.lat,p.lon,R.radius===1000?14:R.radius===3000?13:12);maps.insightmap.insightReport=R;drawMap('insightmap')}
const insightBaseDraw=drawMap;drawMap=function(id){insightBaseDraw(id);const m=maps[id],R=m?.insightReport,el=$(id);if(!R||!el)return;const box=el.getBoundingClientRect(),c=world(m.lat,m.lon,m.z),left=c[0]-box.width/2,top=c[1]-box.height/2;for(const x of (R.nearby.provider==='Google Maps'?[]:R.nearby.places).slice(0,30)){const q=world(x.lat,x.lon,m.z);if(q[0]-left<0||q[0]-left>box.width||q[1]-top<0||q[1]-top>box.height)continue;const dot=document.createElement('a');dot.className='poidot';dot.style.left=q[0]-left+'px';dot.style.top=q[1]-top+'px';dot.title=x.name;dot.textContent=['school','college','university'].includes(x.category)?'E':['hospital','clinic'].includes(x.category)?'H':'T';dot.href=x.url;el.querySelector('.mapoverlay').appendChild(dot)}for(const x of [...R.developments.projects,...firmProjects()].slice(0,25)){const q=world(x.lat,x.lon,m.z);if(q[0]-left<0||q[0]-left>box.width||q[1]-top<0||q[1]-top>box.height)continue;const a=document.createElement('a');a.className='poidot devdot';a.style.left=q[0]-left+'px';a.style.top=q[1]-top+'px';a.textContent='D';a.title=x.name||x.title;a.href=x.sourceUrl||x.source;el.querySelector('.mapoverlay').appendChild(a)}el.querySelector('.refpin')?.removeAttribute('onclick')};
async function requestNarrative(b){if(!Insight.report)return;if(Firm.mode!=='live'||!Firm.token){toast('Connect a deployed firm backend with an AI model configured. Data-based highlights already work.');return}b.disabled=true;b.textContent='Generating source-grounded explanation…';try{const r=await firmCall('POST','/api/intelligence/narrative',{plotCode:Insight.report.plot.code,radius:Insight.radius,question:Insight.query});Insight.modelText=r.enabled?r.text:r.text+' No AI narrative was generated.';plotAIPage()}catch(e){toast(e.message);b.disabled=false;b.textContent='Explain these sources with AI'}}
function shareInsights(){const R=Insight.report;if(!R)return;shareText('Plot source summary',`Plot ${R.plot.code}\n${R.plot.village}\n${dataHighlights(R).map(x=>x.replace(/<[^>]+>/g,'')).join('\n')}\nSources: ${R.plot.source}\n${R.developments.source||''}\nMap data: ${R.nearby.provider}\nChecked: ${R.fetchedAt}\nDistances are approximate straight-line distances. No valuation, return forecast or title verification is provided.`)}
function developmentPage(){$('app').innerHTML=`${backbtn()}<div class="eyebrow">DATED PROJECT EVIDENCE</div><h1>Add development update</h1><div class="notice blue">Record a source and its date. The chosen status is a user/firm claim and will not be labelled independently verified.</div>${enterprise()&&!manager()?'<div class="notice">A manager must add shared development updates.</div>':`<form class="panel" onsubmit="saveDevelopment(event)">${input('Project title','title','','text',true)}<div class="grid">${input('Latitude','lat',Insight.report?.plot.lat,'number',true,'step="any" min="-85" max="85"')}${input('Longitude','lon',Insight.report?.plot.lon,'number',true,'step="any" min="-180" max="180"')}</div>${select('Status stated in your source','status',['Proposed','Approved','Tendered','Under construction','Operational','Unknown'],'Unknown')}${input('HTTPS evidence URL','sourceUrl','','url',true)}${input('Source publication date','sourceDate','','date',true)}<label>Evidence notes</label><textarea name="note" maxlength="1000"></textarea><div class="space"></div><button class="btn full">Save ${Firm.mode==='live'?'shared':'local'} source record</button></form>`}`}
async function saveDevelopment(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.lat=+d.lat;d.lon=+d.lon;try{const u=new URL(d.sourceUrl);if(u.protocol!=='https:'||u.username||u.password)throw Error('Use an HTTPS source URL without credentials.');d.sourceUrl=u.href;if(!coords(d.lat,d.lon))throw Error('Enter valid coordinates');if(Firm.mode==='live'&&Firm.token){await firmAction('POST','/api/developments',d)}else{d.id=uid('dev');d.checkedAt=new Date().toISOString();if(Firm.mode==='demo'){Firm.data.developments=Firm.data.developments||[];Firm.data.developments.push(d);saveDemo()}else{Insight.projects.push(d);localStorage.setItem('insight_projects_310',JSON.stringify(Insight.projects))}}toast('Source record added; status remains a user claim');go('plotAI')}catch(e){toast(e.message)}}

function investmentCashflows(price,growth,acquisition,holding,selling,n=10){const upfront=price*(1+acquisition/100),gross=price*(1+growth/100)**n,net=gross*(1-selling/100),flows=[-upfront,...Array(n-1).fill(-holding),net-holding];return {upfront,gross,net,flows,totalCost:upfront+n*holding,profit:net-upfront-n*holding}}
function irr(flows){const npv=r=>flows.reduce((s,c,i)=>s+c/(1+r)**i,0);let lo=-.999,hi=10,a=npv(lo),b=npv(hi);if(!Number.isFinite(a)||a*b>0)return null;for(let i=0;i<100;i++){const mid=(lo+hi)/2,v=npv(mid);if(v>0)lo=mid;else hi=mid}return (lo+hi)/2*100}
function calcGrowth(input){const n=10,rates=input.rates;return rates.map(g=>{const r=investmentCashflows(input.price,g,input.acquisition,input.holding,input.selling,n),pvCost=r.upfront+Array.from({length:n},(_,i)=>input.holding/(1+input.inflation/100)**(i+1)).reduce((a,b)=>a+b,0),realExit=r.net/(1+input.inflation/100)**n;return {...r,rate:g,irr:irr(r.flows),roi:r.profit/r.totalCost*100,realExit,realGain:realExit-pvCost,values:Array.from({length:11},(_,i)=>input.price*(1+g/100)**i)}})}
function investmentPage(){Growth.result=calcGrowth(Growth);const rows=Growth.result;$('app').innerHTML=`${backbtn()}<div class="hero"><div class="eyebrow">10-YEAR INVESTMENT SCENARIOS</div><h1>Model the possibilities.<br>Keep the assumptions visible.</h1><p>Illustrative growth paths, costs, cash flows and inflation. No forecast is inferred from the plot code or nearby projects.</p></div><div class="notice">Editable scenarios, not a prediction or guaranteed return. Actual plot prices can fall, stagnate or be difficult to realize. ${esc(Growth.label)}</div><form class="panel" onsubmit="updateGrowth(event)"><h2>Your inputs</h2>${input('Purchase price (INR)','price',Growth.price,'number',true,'min="1000" max="1000000000000" step="0.01"')}<div class="grid">${input('Acquisition costs (%)','acquisition',Growth.acquisition,'number',true,'min="0" max="30" step="0.01"')}${input('Annual holding cost (INR)','holding',Growth.holding,'number',true,'min="0" max="100000000" step="0.01"')}${input('Sale costs (%)','selling',Growth.selling,'number',true,'min="0" max="30" step="0.01"')}${input('Inflation assumption (%)','inflation',Growth.inflation,'number',true,'min="0" max="20" step="0.1"')}</div><h3 style="margin-top:20px">Annual appreciation assumptions</h3><div class="grid">${input('Downside rate (%)','rate0',Growth.rates[0],'number',true,'min="-20" max="40" step="0.1"')}${input('Moderate rate (%)','rate1',Growth.rates[1],'number',true,'min="-20" max="40" step="0.1"')}${input('Higher-growth rate (%)','rate2',Growth.rates[2],'number',true,'min="-20" max="40" step="0.1"')}</div><p class="mini muted">Starting rates −2%, 5% and 8% are hypothetical examples, not estimates for Amaravati. Costs and inflation start at zero; enter your actual assumptions. Taxes, borrowing costs and rental income are excluded.</p><button class="btn full">Recalculate 10-year outlook</button></form><div class="panel"><h2>Illustrative gross value paths</h2>${growthChart(rows)}<small>Before acquisition, holding and sale costs. The model assumes a constant annual growth rate in each scenario.</small></div><div class="scenariocards">${rows.map((r,i)=>`<div class="panel"><div class="row"><span class="tag ${i===0?'red':i===1?'':'amber'}">${['DOWNSIDE','MODERATE','HIGHER GROWTH'][i]} • ${r.rate}% / YEAR</span><small>Year 10</small></div><div class="price" style="margin-top:12px">${money(r.gross)}</div><small>Illustrative gross property value</small><div class="facts">${fact('Net sale proceeds',money(r.net))}${fact('Total cash outlay',money(r.totalCost))}${fact('Nominal net gain / loss',signedMoney(r.profit))}${fact('Return on cash outlay',r.roi.toFixed(1)+'%')}${fact('Annual cash-flow IRR',r.irr===null?'Not available':r.irr.toFixed(2)+'%')}${fact('Real net gain / loss',signedMoney(r.realGain))}</div><small>Real gain compares inflation-discounted sale proceeds with inflation-discounted cash costs. IRR assumes year-end holding costs and a sale at the end of year 10.</small></div>`).join('')}</div><div class="panel"><h2>Year-by-year property value</h2><div class="scroll" style="max-height:none"><table class="previewtable"><thead><tr><th>Year</th><th>${rows[0].rate}%</th><th>${rows[1].rate}%</th><th>${rows[2].rate}%</th></tr></thead><tbody>${Array.from({length:11},(_,n)=>`<tr><td>${n===0?'Today':n}</td>${rows.map(r=>`<td>${money(r.values[n])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><details><summary>How to interpret this outlook</summary><p class="mini">Gross value = purchase price × (1 + annual assumption) raised to the year. Net proceeds subtract assumed sale costs. Nominal gain subtracts acquisition and all ten annual holding payments. No borrowing, tax, rental income or future cost escalation is modelled.</p><p class="mini">Nearby schools and proposed projects do not automatically determine appreciation. Check actual comparable transactions, permitted use, title, infrastructure execution and exit liquidity independently.</p><a href="https://www.rbi.org.in/scripts/FS_PressRelease.aspx?prid=63436">RBI historical house-price index context ↗</a><small style="display:block">A broad historical housing index is not a forecast for an individual CRDA plot. Example assumptions here are not calibrated from that index.</small></details><button class="btn full" onclick="shareGrowth()">Share assumptions & scenario results</button>`}
function signedMoney(v){if(Math.abs(v)<.005)return '₹0';return (v<0?'−':'+')+money(Math.abs(v))}
function updateGrowth(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),rates=[+d.rate0,+d.rate1,+d.rate2];if(rates[0]>rates[1]||rates[1]>rates[2]){toast('Keep downside ≤ moderate ≤ higher-growth assumptions.');return}for(const k of ['price','acquisition','holding','selling','inflation'])Growth[k]=+d[k];Growth.rates=rates;Growth.label='User-entered assumptions, not a market valuation.';investmentPage();toast('Scenario calculations updated')}
function growthChart(rows){const W=320,H=190,L=38,R=25,T=16,B=30,max=Math.max(...rows.flatMap(r=>r.values))*1.06,min=0,x=n=>L+n/10*(W-L-R),y=v=>H-B-(v-min)/(max-min)*(H-T-B);return `<svg viewBox="0 0 ${W} ${H}" class="growthchart" role="img" aria-label="Illustrative ten-year property value paths">${[0,.5,1].map(v=>`<line x1="${L}" y1="${y(max*v)}" x2="${W-R}" y2="${y(max*v)}" stroke="#dce7eb"/><text x="${L-4}" y="${y(max*v)+3}" text-anchor="end">${(max*v/1e5).toFixed(0)}L</text>`).join('')}${[0,5,10].map(n=>`<text x="${x(n)}" y="${H-10}" text-anchor="middle">${n===0?'Today':'Year '+n}</text>`).join('')}${rows.map((r,i)=>`<path d="${r.values.map((v,n)=>(n?'L':'M')+x(n)+','+y(v)).join(' ')}" fill="none" stroke="${['#b65d5d','#ea580c','#c58a35'][i]}" stroke-width="2.5"/>`).join('')}</svg><div class="row mini"><span style="color:#b65d5d">Downside</span><span style="color:#ea580c">Moderate</span><span style="color:#c58a35">Higher growth</span></div>`}
function shareGrowth(){shareText('Illustrative 10-year property scenarios',`ILLUSTRATIVE SCENARIOS - NOT A FORECAST\nPurchase: ${money(Growth.price)}\nAcquisition: ${Growth.acquisition}% | Annual holding: INR ${Growth.holding} | Sale costs: ${Growth.selling}% | Inflation: ${Growth.inflation}%\n${calcGrowth(Growth).map((r,i)=>`${['Downside','Moderate','Higher growth'][i]} (${r.rate}%/year): year-10 gross ${money(r.gross)}, nominal net gain/loss ${signedMoney(r.profit)}, cash-flow IRR ${r.irr?.toFixed(2)}%`).join('\n')}\nTaxes, borrowing and rental income excluded. No plot-code-based appreciation forecast or guaranteed return is provided.`)}
route='firm';args={};render();

// Separate buyer and seller presentation; authorization remains server-side.
const Market={side:'',demo:false,user:null,catalog:[],inventory:[],requests:[],saved:[],compare:[],profile:{},active:null,thread:null,filter:{q:'',type:'',city:'',maxPrice:'',purpose:''},busy:false,security:null,setup:null,recovery:[],retry:new Map(),edit:null};
const marketBase={render,header,persist,firmPage,saveEndpoint};
const SELLER_ROLES=['owner','manager','agent','viewer'];
function marketLive(){return !Market.demo&&!!Firm.token&&!!Market.user}
function buyerSide(){return Market.side==='buyer'}
function sellerAdmin(){return Market.user&&['owner','manager'].includes(Market.user.role)}
function sellerWrite(){return Market.user&&['owner','manager','agent'].includes(Market.user.role)}
function loadMarketDemo(){let d;try{d=JSON.parse(localStorage.getItem('market_demo400'))}catch(e){}if(!d){const ps=DEMOS.map((p,i)=>({...p,id:'dp'+i,published:i<3,version:1,views:0,insights:i===1?{projectName:'Demo Garden Residences',builder:'Demo Builder',constructionStatus:'Resale / ready',areaBasis:'Super built-up',carpetArea:1100,superArea:1450,baths:3,balconies:2,floor:4,totalFloors:10,age:5,parking:2,lifts:2,maintenance:3000,uds:35,rera:'DEMO-RERA-0000',oc:'Not supplied',cc:'Not supplied',water:'Seller claim: supply available',power:'Seller claim: backup',amenities:['Lift','Security','Play area']}:{lengthM:18,widthM:12,roadStatus:'Seller claim: formed road',water:'Not independently checked',power:'Not independently checked',drainage:'Not supplied',landUse:'Seller claim: residential',boundary:'Site survey pending'}}));d={properties:ps,requests:[],saved:[],profile:{}};localStorage.setItem('market_demo400',JSON.stringify(d))}return d}
let marketDemo=loadMarketDemo();
function saveMarketDemo(){localStorage.setItem('market_demo400',JSON.stringify(marketDemo))}
function startMarketDemo(side){Firm.token='';Firm.mode=side==='buyer'?'buyer-demo':'demo';Market.demo=true;Market.side=side;Market.user=side==='buyer'?{id:'demoBuyer',name:'Ananya • Demo Buyer',email:'buyer@example.invalid',role:'buyer'}:{id:'do',name:'Ravi • Demo Seller',email:'seller@example.invalid',role:'owner'};Firm.data=freshDemo();Firm.data.user=Market.user;Firm.data.properties=marketDemo.properties;Market.inventory=marketDemo.properties;Market.catalog=marketDemo.properties.filter(p=>p.published);Market.requests=marketDemo.requests;Market.saved=marketDemo.saved;Market.profile=marketDemo.profile;state.listings=Market.inventory;loadBuyerPrivate();route=side==='buyer'?'buyerHome':'sellerHome';args={};stack=[];render()}
function loadBuyerPrivate(){if(!buyerSide())return;let v={};try{v=JSON.parse(localStorage.getItem('market_private_'+hash(Firm.endpoint+'|'+Market.user.id))||'{}')}catch(e){}state.checks=v.checks||{};state.notes=v.notes||{}}
persist=function(){if(Market.user&&buyerSide()){try{const b=JSON.parse(localStorage.getItem(KEY)||lastGood);b.refs=state.refs;b.imports=state.imports;b.lang=state.lang;localStorage.setItem(KEY,JSON.stringify(b));localStorage.setItem('market_private_'+hash(Firm.endpoint+'|'+Market.user.id),JSON.stringify({checks:state.checks,notes:state.notes}));return true}catch(e){toast('Cannot save private notes on this device');return false}}return marketBase.persist()};
async function marketCall(method,path,data={}){const sensitive=path.startsWith('/api/security/')||path.endsWith('/ticket'),sig=method+path+JSON.stringify(data);let key=!sensitive&&method==='POST'?(Market.retry.get(sig)||uid('op')):'';if(key)Market.retry.set(sig,key);const r=await firmCall(method,path,data,key);Market.retry.delete(sig);return r}
async function refreshMarket(redraw=true){if(Market.busy||!marketLive())return;Market.busy=true;const session=Firm.token;try{if(buyerSide()){const [d,cat]=await Promise.all([marketCall('GET','/api/buyer/dashboard'),marketCall('GET','/api/market/catalog?'+new URLSearchParams(Market.filter))]);if(session!==Firm.token)return;Market.requests=d.requests;Market.saved=d.saved;Market.profile=d.profile;Market.catalog=cat.properties;state.listings=Market.catalog}else{await firmRefresh(false);if(session!==Firm.token)return;if(Market.user.role==='viewer'){Market.inventory=Firm.data.properties;Market.requests=[]}else{const d=await marketCall('GET','/api/seller/dashboard');Market.inventory=d.properties;Market.requests=d.requests}state.listings=Market.inventory}if(redraw)render()}catch(e){toast(e.message)}finally{Market.busy=false}}
setInterval(()=>{if(marketLive()&&!document.hidden&&['home','saved','buyerHome','sellerHome','catalog','sellerInventory','marketSaved','marketRequests'].includes(route))refreshMarket()},30000);
async function marketLogout(){try{if(Firm.token)await firmCall('POST','/api/auth/logout')}catch(e){}Firm.token='';Firm.mode='local';Firm.data=null;Market.user=null;Market.demo=false;Market.side='';Market.active=null;Market.thread=null;Market.setup=null;Market.recovery=[];Market.requests=[];Market.catalog=[];Market.inventory=[];Market.retry.clear();Market.compare=[];Market.saved=[];Market.security=null;restoreLocal();route='portal';args={};stack=[];render()}
header=function(){if(!Market.side){$('header').innerHTML=`<div class="mark">${icon('home')}</div><div class="brand"><strong>Agent Mart</strong><small>PROPERTY • EVIDENCE • PEOPLE</small></div><button class="iconbtn" aria-label="Connection settings" onclick="go('firmSettings')">${icon('crda')}</button>`;$('nav').innerHTML='';return}const isb=buyerSide();$('header').innerHTML=`<div class="mark">${icon('home')}</div><div class="brand"><strong>Agent Mart</strong><small>${isb?'BUYER':'SELLER'} ${Market.demo?'• DEMO':'WORKSPACE'}</small></div><button class="iconbtn" aria-label="Notifications and enquiries" onclick="go('marketRequests')">${icon('legal')}</button><button class="avatarbtn" aria-label="Account" onclick="go('marketAccount')">${esc((Market.user?.name||'A').slice(0,1))}</button>`;const tabs=isb?[['buyerHome','home','Home'],['catalog','search','Explore'],['marketSaved','saved','Saved'],['marketRequests','legal','Enquiries'],['marketAccount','crda','Account']]:[['sellerHome','home','Overview'],['sellerInventory','search','Inventory'],['marketRequests','legal','Enquiries'],['plotAI','map','Insights'],['marketAccount','crda','Account']];$('nav').innerHTML=tabs.map(([r,i,l])=>`<button class="${route===r?'active':''}" onclick="go('${r}')">${icon(i)}<span>${l}</span></button>`).join('');document.body.dataset.side=Market.side};
render=function(){if(Market.user&&!Market.demo&&!Firm.token){Market.user=null;Market.side='';route='portal'}if(route==='firm'){route=Market.user?(buyerSide()?'buyerHome':'sellerHome'):'portal'}if(route==='firmAuth'){route='marketAuth';args={side:Market.side||'seller',mode:args.mode||'login'}}const pages={portal:portalPage,marketAuth:marketAuthPage,buyerHome:buyerHome,sellerHome:sellerHome,catalog:catalogPage,sellerInventory:sellerInventory,marketProperty:marketProperty,marketSaved:savedMarket,marketCompare:compareMarket,marketRequests:requestsMarket,marketThread:threadMarket,sellerEdit:sellerEditor,marketAccount:accountMarket,marketSecurity:securityMarket,dossier:dossierPage};if(pages[route]){header();if(window.AndroidApp?.setSecureScreen)AndroidApp.setSecureScreen(['marketAuth','marketSecurity','marketThread'].includes(route));try{pages[route]()}catch(e){console.error(e);$('app').innerHTML=empty('Unable to open this view','Your server records have not been changed.')}return}if(buyerSide()&&['team','branches','activity','firmMore','reports','edit','leadEdit','visits'].includes(route)){header();$('app').innerHTML=empty('Seller workspace is private','Buyer accounts cannot access firm administration.');return}if(window.AndroidApp?.setSecureScreen)AndroidApp.setSecureScreen(['firmPassword'].includes(route));marketBase.render()};
function sessionBanner(){return `<div class="sessionbanner"><span>${Market.demo?'ILLUSTRATIVE DEMO • NO REAL ACCOUNT':buyerSide()?'BUYER ACCOUNT':'SELLER / FIRM ACCOUNT'}</span><span>${Market.demo?'Local sample': 'Server connected'}</span></div>`}
function portalPage(){$('app').innerHTML=`<div class="portalhero"><div class="eyebrow">AGENT MART • BUY & SELL WITH CONTEXT</div><h1>Find your next place.<br><em>Understand every detail.</em></h1><p>A separate workspace for property buyers and sellers, with source-led plot and flat insights.</p><div class="portalart">${buildingArt()}</div></div><div class="rolecards"><button class="rolecard" onclick="chooseMarketSide('buyer')"><span class="roleicon">${icon('search')}</span><h2>I'm a buyer</h2><p>Explore, compare, ask questions and track your property journey.</p><strong>Buyer sign in →</strong></button><button class="rolecard sellerrole" onclick="chooseMarketSide('seller')"><span class="roleicon">${icon('home')}</span><h2>I'm a seller</h2><p>List property, manage buyer enquiries and control document access.</p><strong>Seller sign in →</strong></button></div><div class="trustline"><span>Separate accounts</span><span>Evidence-linked insights</span><span>Private documents</span></div><div class="panel"><div class="row"><h3>Explore before connecting</h3><span class="tag amber">DEMO</span></div><p class="mini muted">Fictional listings and reports show the full flow. Live accounts require your deployed HTTPS backend.</p><div class="row"><button class="btn secondary grow" onclick="startMarketDemo('buyer')">Buyer demo</button><button class="btn outline grow" onclick="startMarketDemo('seller')">Seller demo</button></div></div><button class="btn outline full" onclick="go('firmSettings')">Connect deployed backend</button>`}
function chooseMarketSide(side){Market.side=side;go('marketAuth',{side,mode:'login'})}
function marketAuthPage(){const side=args.side||Market.side||'buyer',mode=args.mode||'login';Market.side=side;const seller=side==='seller';$('app').innerHTML=`${backbtn()}<div class="authwelcome"><span class="tag">${seller?'SELLER / FIRM':'BUYER'} ACCOUNT</span><h1>${mode==='login'?'Welcome back.':mode==='join'?'Join your firm.':'Start your property journey.'}</h1><p>${seller?'Your inventory, enquiries and source documents.':'Your shortlist, comparisons, conversations and visits.'}</p></div><div class="chips">${[['login','Sign in'],['register','Create account'],...(seller?[['join','Staff invitation']]:[])].map(([m,l])=>`<button class="chip ${mode===m?'active':''}" onclick="args.mode='${m}';marketAuthPage()">${l}</button>`).join('')}</div><form class="panel" onsubmit="marketAuthenticate(event,'${side}','${mode}')">${mode!=='login'?input('Your name','name','','text',true):''}${seller&&mode==='register'?input('Seller / real estate firm name','firmName','','text',true):''}${input('Email','email','','email',true)}${input('Password / passphrase','password','','password',true,`minlength="${mode==='login'?10:15}" maxlength="200" autocomplete="${mode==='login'?'current-password':'new-password'}"`)}${mode==='join'?input('One-time staff invitation code','inviteCode','','text',true):''}${mode==='login'?input('Authenticator / recovery code (if enabled)','otp','','text',false,'autocomplete="one-time-code"'):''}<div class="space"></div><button class="btn full" type="submit">${mode==='login'?'Sign in to '+side+' dashboard':mode==='join'?'Accept staff invitation':'Create '+side+' account'}</button></form><p class="tabnote">${Firm.endpoint?'Backend: '+esc(Firm.endpoint):'No backend configured. Connect your hosted server before creating real accounts.'}</p><button class="btn outline full" onclick="go('firmSettings')">Connection settings</button><p class="footertext">Buyer and seller accounts have different permissions. A sign-in or authenticator code does not verify property ownership. Password recovery requires your server administrator; automated recovery email is not configured.</p>`}
async function marketAuthenticate(e,side,mode){e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.expectedSide=side;const path=mode==='login'?'/api/auth/login':mode==='join'?'/api/auth/join':side==='buyer'?'/api/auth/register-buyer':'/api/auth/register';const origin=Firm.endpoint,r=await firmCall('POST',path,d);if(origin!==Firm.endpoint)throw Error('Backend changed. Sign in again.');Market.side=r.user.role==='buyer'?'buyer':'seller';Market.demo=false;Market.user=r.user;Firm.token=r.token;Firm.mode=buyerSide()?'buyer-live':'live';Firm.data={user:r.user};Market.requests=[];restoreLocal();loadBuyerPrivate();await refreshMarket(false);route=buyerSide()?'buyerHome':'sellerHome';args={};stack=[];render();window.scrollTo(0,0)}catch(e){toast(e.message)}finally{b.disabled=false}}
function buildingArt(){return `<svg viewBox="0 0 420 190" aria-label="Illustrative building and plot"><ellipse cx="210" cy="167" rx="180" ry="18" fill="#7c2d1210"/><path d="M35 144 164 116 263 145 132 176Z" fill="#c5ddd4" stroke="#88b8a4"/><path d="m56 144 107-21 75 23-108 22Z" fill="none" stroke="#fff" stroke-dasharray="5 4"/><path d="m187 133 0-100 69-20 95 35v100l-69 24Z" fill="#f7f1df"/><path d="m256 13 95 35v100l-69 24-26-10Z" fill="#c2d6df"/><path d="m180 34 77-29 102 37-9 13-96-28-66 20Z" fill="#224f68"/>${[0,1,2].flatMap(i=>[0,1,2].map(j=>`<path d="m${198+i*18} ${50+j*25-i*5} 11-3v16l-11 3Z" fill="#7da8b6"/>`)).join('')}<path d="M271 59v18l18 7V66ZM306 71v18l18 6V78ZM271 94v18l18 7V101ZM306 106v18l18 6V113Z" fill="#638da1"/><path d="m236 123 15-4v42l-15-4Z" fill="#d3a05b"/><circle cx="367" cy="126" r="25" fill="#a4c6b2"/><path d="M367 136v29" stroke="#5c8c75" stroke-width="5"/></svg>`}
function assetArt(p){return p.type==='Apartment'?buildingArt():illustration(p)}
function marketCard(p,seller=false){const saved=Market.saved.includes(p.id);return `<article class="marketcard"><div class="cardvisual" onclick="go('marketProperty',{id:'${p.id}'})">${p.photo?`<img src="${p.photo}" alt="Property photo">`:assetArt(p)}<span class="tag ${Market.demo?'amber':''}">${Market.demo?'FICTIONAL SAMPLE':seller?(p.published?'PUBLISHED':'PRIVATE DRAFT'):'SELLER PUBLISHED'}</span><small>${p.photo?'Seller photo':'Illustration - not a property photo'}</small></div><div class="cardbody"><div class="row"><span class="categoryline">${esc(p.type)} · ${esc(p.purpose)}</span>${!seller?`<button aria-label="Save property" onclick="marketSave('${p.id}')">${saved?'♥':'♡'}</button>`:''}</div><h3 onclick="go('marketProperty',{id:'${p.id}'})">${esc(p.title)}</h3><small>${icon('pin')} ${esc(p.village)}, ${esc(p.city)}</small><div class="meta"><span>${fmt(p.area)} ${esc(p.unit)}</span><span>${p.bhk?esc(p.bhk)+' BHK':esc(p.facing||'Facing not supplied')}</span></div><div class="row"><div class="price">${money(p.price)}${p.purpose==='Rent'?'<small>/mo</small>':''}</div><button class="btn secondary" onclick="go('marketProperty',{id:'${p.id}'})">Details</button></div>${seller?`<small>${p.views||0} unique buyer/day detail opens · ${p.published?'Edit changes require republication.':'Not visible to live buyers.'}</small>`:`<div class="cardtools"><button onclick="toggleCompare('${p.id}')">${Market.compare.includes(p.id)?'✓ Selected':'＋ Compare'}</button><button onclick="go('dossier',{id:'${p.id}'})">Insights →</button></div>`}</div></article>`}
function localCatalog(){const f=Market.filter;return marketDemo.properties.filter(p=>p.published&&(!f.q||[p.title,p.village,p.city,p.plotCode,p.survey].join(' ').toLowerCase().includes(f.q.toLowerCase()))&&(!f.type||p.type===f.type)&&(!f.city||p.city.toLowerCase().includes(f.city.toLowerCase()))&&(!f.maxPrice||p.price<=+f.maxPrice)&&(!f.purpose||p.purpose===f.purpose))}
async function searchMarket(e){if(e){e.preventDefault();Object.assign(Market.filter,Object.fromEntries(new FormData(e.target)))}if(Market.demo){Market.catalog=localCatalog();catalogPage()}else{try{const r=await marketCall('GET','/api/market/catalog?'+new URLSearchParams(Market.filter));Market.catalog=r.properties;catalogPage()}catch(e){toast(e.message)}}}
function buyerHome(){$('app').innerHTML=`${sessionBanner()}<div class="buyerhero"><div class="eyebrow">HELLO, ${esc(Market.user.name.split(' ')[0]).toUpperCase()}</div><h1>A home for your<br><em>next big decision.</em></h1><p>Discover the property. Understand the evidence.</p><button class="btn" onclick="go('catalog')">${icon('search')} Explore properties</button>${buildingArt()}</div><div class="metricrow"><button onclick="go('marketSaved')"><strong>${Market.saved.length}</strong><span>Saved</span></button><button onclick="go('marketRequests')"><strong>${Market.requests.length}</strong><span>Enquiries</span></button><button onclick="go('marketCompare')"><strong>${Market.compare.length}</strong><span>Compare</span></button></div><div class="discoverytiles"><button onclick="Market.filter.type='Plot';go('catalog');searchMarket()">${icon('crda')}<b>Plots & land</b><small>Identity, boundary & access</small></button><button onclick="Market.filter.type='Apartment';go('catalog');searchMarket()">${icon('home')}<b>Flats & apartments</b><small>Area, project & readiness</small></button></div><div class="row sectionhead"><h2>Explore your options</h2><button onclick="go('catalog')">View all →</button></div><div class="cards">${Market.catalog.slice(0,4).map(p=>marketCard(p)).join('')||empty('No published inventory yet','Sellers must explicitly publish an available property before it appears here.')}</div><div class="insightentry"><span class="eyebrow">LOOK BEYOND THE LISTING</span><h3>Evidence before assumptions.</h3><p>Inspect the plot or flat, review missing records, and keep future-value scenarios separate from verified facts.</p><div class="row"><button class="btn grow" onclick="go('plotAI')">Plot research</button><button class="btn secondary grow" onclick="go('investment')">10-year scenarios</button></div></div>`}
function catalogPage(){$('app').innerHTML=`${sessionBanner()}<div class="eyebrow">CURATED BY YOUR FILTERS</div><h1>Find your place.</h1><form class="panel" onsubmit="searchMarket(event)"><div class="searchline"><input name="q" aria-label="Search properties" value="${esc(Market.filter.q)}" placeholder="Location, project, survey or plot code"><button class="btn" aria-label="Search">${icon('search')}</button></div><div class="grid"><div><label>Property type</label><select name="type"><option value="">All types</option>${['Plot','Apartment','House','Commercial','Farm land'].map(t=>`<option ${Market.filter.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label>Purpose</label><select name="purpose"><option value="">Buy or rent</option>${options(['Sale','Rent'],Market.filter.purpose)}</select></div><div><label>City</label><input name="city" value="${esc(Market.filter.city)}" placeholder="Any city"></div><div><label>Maximum budget (INR)</label><input name="maxPrice" type="number" min="0" value="${esc(Market.filter.maxPrice)}" placeholder="No limit"></div></div><button class="btn secondary full" style="margin-top:14px">Apply filters</button></form><div class="row sectionhead"><h2>Properties</h2><small>${Market.catalog.length} returned</small></div><div class="cards">${Market.catalog.map(p=>marketCard(p)).join('')||empty('No matching properties','Try another location or budget.')}</div>${Market.compare.length?`<div class="stickyaction row"><span>${Market.compare.length}/3 selected</span><button class="btn" onclick="go('marketCompare')">Compare now</button></div>`:''}<p class="footertext">Seller-published claims are not independently verified. Search results are capped; they are not all properties on the market.</p>`}
async function marketSave(id){if(Market.demo){Market.saved=Market.saved.includes(id)?Market.saved.filter(x=>x!==id):[...Market.saved,id];marketDemo.saved=Market.saved;saveMarketDemo();render();return}try{await marketCall(Market.saved.includes(id)?'DELETE':'POST','/api/buyer/saved/'+id);await refreshMarket();toast('Shortlist updated')}catch(e){toast(e.message)}}
function toggleCompare(id){if(Market.compare.includes(id))Market.compare=Market.compare.filter(x=>x!==id);else{if(Market.compare.length>=3){toast('Compare up to three properties');return}Market.compare.push(id)}render()}
function savedMarket(){$('app').innerHTML=`${sessionBanner()}<div class="eyebrow">YOUR PRIVATE SHORTLIST</div><h1>Saved properties</h1><div class="cards">${Market.catalog.filter(p=>Market.saved.includes(p.id)).map(p=>marketCard(p)).join('')||empty('Your shortlist is empty','Save a property from Explore to revisit it here.')}</div>${Market.saved.some(id=>!Market.catalog.some(p=>p.id===id))?'<div class="notice">Some saved listings are not in the current catalogue view or are no longer published.</div>':''}<button class="btn outline full" style="margin-top:16px" onclick="go('marketCompare')">Compare selected properties (${Market.compare.length})</button>`}
function compareMarket(){const ps=Market.catalog.filter(p=>Market.compare.includes(p.id));$('app').innerHTML=`${backbtn()}<div class="eyebrow">SIDE-BY-SIDE DECISIONS</div><h1>Property comparison</h1>${ps.length?`<div class="panel comparewrap"><table class="comparetable"><thead><tr><th>Field</th>${ps.map(p=>`<th>${esc(p.title)}</th>`).join('')}</tr></thead><tbody>${[['Asking price',p=>money(p.price)],['Property type',p=>p.type],['Location',p=>p.city],['Listed area',p=>fmt(p.area)+' '+p.unit],['Area basis',p=>p.insights?.areaBasis||'Not supplied'],['Bedrooms',p=>p.bhk||'Not supplied'],['Carpet area',p=>p.insights?.carpetArea?fmt(p.insights.carpetArea)+' sq ft':'Not supplied'],['Facing',p=>p.facing||'Not supplied'],['Road width',p=>p.road?fmt(p.road)+' m':'Not supplied'],['RERA reference',p=>p.insights?.rera||'Not supplied'],['OC availability',p=>p.insights?.oc||'Not supplied']].map(([k,fn])=>`<tr><td>${k}</td>${ps.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="notice blue">Compare equal area bases and property types. A plot area and a flat's super built-up area describe different things.</p>`:empty('Select properties first','Tap Compare on up to three listings.')}`}
function sellerHome(){const ps=Market.inventory,reqs=Market.requests;$('app').innerHTML=`${sessionBanner()}<div class="sellerhero"><div><div class="eyebrow">YOUR PROPERTY BUSINESS, IN VIEW</div><h1>${esc(Market.user.name.split(' ')[0])},<br>make every listing count.</h1><p>Manage your inventory, buyer interest and evidence.</p>${sellerWrite()?'<button class="btn" onclick="go(\'sellerEdit\')">+ List a property</button>':''}</div><div class="sellerart">${buildingArt()}</div></div><div class="sellerstats"><div><strong>${ps.length}</strong><span>Inventory</span></div><div><strong>${ps.filter(p=>p.published).length}</strong><span>Published</span></div><div><strong>${reqs.filter(r=>r.status==='Pending').length}</strong><span>New enquiries</span></div><div><strong>${ps.reduce((n,p)=>n+(p.views||0),0)}</strong><span>Buyer/day opens</span></div></div><div class="row sectionhead"><h2>Your next actions</h2><button onclick="go('sellerInventory')">Inventory →</button></div><div class="actiongrid"><button class="actiontile" onclick="go('marketRequests')">${icon('legal')}<strong>Respond to buyers</strong></button><button class="actiontile" onclick="go('sellerInventory')">${icon('home')}<strong>Review private drafts</strong></button><button class="actiontile" onclick="go('plotAI')">${icon('map')}<strong>Research a plot</strong></button><button class="actiontile" onclick="go('marketSecurity')">${icon('saved')}<strong>Account protection</strong></button></div><div class="panel" style="margin-top:17px"><h2>Attention needed</h2>${ps.filter(p=>!p.published).slice(0,4).map(p=>`<div class="listrow" onclick="go('marketProperty',{id:'${p.id}'})"><strong>${esc(p.title)}</strong><small>Private inventory. Review details before publishing.</small></div>`).join('')||'<p class="muted">No unpublished listings in your visible inventory.</p>'}</div><div class="row sectionhead"><h2>Recent properties</h2></div><div class="cards">${ps.slice(0,4).map(p=>marketCard(p,true)).join('')||empty('Start your inventory','Add a plot, flat or other property, then review its buyer-facing details.')}</div>`}
function sellerInventory(){$('app').innerHTML=`${sessionBanner()}<div class="row sectionhead"><div><div class="eyebrow">PRIVATE DRAFTS & PUBLISHED LISTINGS</div><h1>My inventory</h1></div>${sellerWrite()?'<button class="btn" onclick="go(\'sellerEdit\')">+ Add</button>':''}</div><div class="cards">${Market.inventory.map(p=>marketCard(p,true)).join('')||empty('No inventory yet','Add your first property to start.')}</div>`}
async function marketProperty(){const session=Firm.token;const p=(buyerSide()?Market.catalog:Market.inventory).find(p=>p.id===args.id);if(!p){$('app').innerHTML=empty('Property unavailable','Refresh the catalogue or return to your inventory.');return}Market.active=p;$('app').innerHTML=propertyBody(p);if(!Market.demo){try{if(buyerSide()){const d=await marketCall('GET','/api/market/properties/'+p.id);if(!['marketProperty','detail'].includes(route)||args.id!==p.id||session!==Firm.token)return;Market.active={...p,...d.property};$('app').innerHTML=propertyBody(Market.active)}if(p.hasPhoto&&!p.photo){const r=await marketCall('GET',buyerSide()?'/api/market/properties/'+p.id+'/photo':'/api/properties/'+p.id+'/photo');if(['marketProperty','detail'].includes(route)&&args.id===p.id&&r.photo){p.photo=r.photo;$('propertyCover').innerHTML=`<img src="${r.photo}" alt="Seller supplied property photo">`}}}catch(e){toast(e.message)}}}
function propertyBody(p){const x=p.insights||{},flat=p.type==='Apartment';return `${backbtn()}<div class="detailcover" id="propertyCover">${p.photo?`<img src="${p.photo}" alt="Property photo">`:assetArt(p)}<span class="tag ${Market.demo?'amber':''}">${Market.demo?'FICTIONAL SAMPLE':p.published||buyerSide()?'SELLER PUBLISHED':'PRIVATE INVENTORY'}</span></div><div class="row" style="margin-top:16px"><span class="categoryline">${esc(p.type)} · ${esc(p.purpose)}</span>${buyerSide()?`<button onclick="marketSave('${p.id}')">${Market.saved.includes(p.id)?'♥ Saved':'♡ Save'}</button>`:''}</div><h1>${esc(p.title)}</h1><p class="muted">${icon('pin')} ${esc(p.village)}, ${esc(p.city)}</p><div class="price">${money(p.price)}${p.purpose==='Rent'?'<small> / month</small>':''}</div><small>${p.area&&p.price?money(p.price/p.area)+' per '+esc(p.unit):''} · Asking price, not an independent valuation</small><div class="featurefacts"><div><strong>${fmt(p.area)}</strong><span>${esc(p.unit)} listed</span></div><div><strong>${flat?(p.bhk||'—')+' BHK':esc(p.facing||'—')}</strong><span>${flat?'Bedrooms':'Facing'}</span></div><div><strong>${flat?(x.floor??'—'):(p.road||'—')}</strong><span>${flat?'Floor':'Road width (m)'}</span></div></div><div class="notice blue">Property facts and approvals shown here are seller-supplied. A published listing is not title, identity or approval verification.</div><div class="panel"><div class="row"><h2>At a glance</h2><span class="tag">${flat?'FLAT':'PLOT / PROPERTY'} INSIGHTS</span></div><div class="facts">${fact('District / mandal',[p.district,p.mandal].filter(Boolean).join(' / '))}${fact('Survey / plot code',p.plotCode||p.survey)}${flat?fact('Project',x.projectName)+fact('Builder',x.builder)+fact('Carpet area',x.carpetArea?fmt(x.carpetArea)+' sq ft':null)+fact('Area basis',x.areaBasis)+fact('RERA reference',x.rera)+fact('Occupancy record',x.oc):fact('Seller-stated land use',x.landUse)+fact('Road condition',x.roadStatus)+fact('Dimensions',x.lengthM&&x.widthM?`${x.lengthM} × ${x.widthM} m`:null)+fact('Boundary check',x.boundary)}</div><button class="btn full" style="margin-top:16px" onclick="go('dossier',{id:'${p.id}'})">Open in-depth property insights →</button></div><div class="panel"><h2>About the property</h2><p>${esc(p.description||'No description supplied.')}</p><div class="amenitychips">${(x.amenities||[]).map(a=>`<span>${esc(a)}</span>`).join('')}</div><small>Amenities are seller claims and may not be operational.</small></div><div class="panel"><h2>Location & surroundings</h2><p class="mini muted">${coords(p.lat,p.lon)?'Coordinates supplied. Verify actual access and boundaries.':'Exact coordinates have not been supplied.'}</p><div class="row">${coords(p.lat,p.lon)?`<a class="btn outline grow" href="${mapsURL(p)}">Open map</a>`:''}<button class="btn secondary grow" onclick="Insight.query='${p.plotCode&&/^\d[\dA-Z-]+$/.test(p.plotCode)?p.plotCode:''}';go('plotAI')">Research plot / area</button></div></div>${buyerSide()?`<div class="panel"><h2>Ask the seller</h2><p class="mini muted">Submit an enquiry with consent. Contact details are released after acceptance; they are not identity-verified.</p><form onsubmit="submitMarketEnquiry(event,'${p.id}')">${input('Your mobile','phone','','tel',true,'pattern="[6-9][0-9]{9}" maxlength="10"')}<label>Your message</label><textarea name="message" required maxlength="2000" placeholder="I would like the property documents and a site visit."></textarea><div class="checkrow" style="margin:14px 0"><input id="enquiryConsent" type="checkbox" required><label for="enquiryConsent">Share my name, message and mobile with this listing's seller firm to respond to this enquiry.</label></div><button class="btn full">Send enquiry</button></form></div><div class="row"><button class="btn outline grow" onclick="toggleCompare('${p.id}')">Compare</button><button class="btn secondary grow" onclick="propertyGrowthFromMarket('${p.id}')">Investment outlook</button></div>`:sellerControls(p)}`}
function sellerControls(p){return `<div class="panel"><h2>Seller controls</h2>${sellerWrite()?`<button class="btn secondary full" onclick="go('sellerEdit',{id:'${p.id}'})">Edit property & insight fields</button>`:''}${sellerAdmin()?p.published?`<button class="btn outline full" style="margin-top:10px" onclick="publishMarket('${p.id}',false)">Withdraw buyer-facing listing</button>`:`<form onsubmit="event.preventDefault();publishMarket('${p.id}',true)"><div class="checkrow" style="margin:16px 0"><input id="publishConsent" type="checkbox" required><label for="publishConsent">I am authorized to advertise this property and have reviewed the buyer-facing facts. Private contact is released only through accepted enquiries.</label></div><button class="btn full">Publish to buyer catalogue</button></form>`:'<p class="mini muted">An owner or manager must approve publication and document sharing.</p>'}</div>${sellerAdmin()?`<div class="panel"><h2>Private source documents</h2><p class="mini muted">Encrypted storage requires a configured server key. PDF/JPEG/PNG only, below 500 KiB. Files are not publicly linked or certified malware-free.</p><form onsubmit="uploadPrivateDocument(event,'${p.id}')">${select('Document type','label',['Title document','Encumbrance record','Approval','RERA reference','Occupancy certificate','Layout','Other'],'Title document')}<label>Private file</label><input name="documentFile" type="file" accept=".pdf,.jpg,.jpeg,.png" required><div class="space"></div><button class="btn outline full" ${Market.demo?'disabled':''}>Upload encrypted document</button></form>${Market.demo?'<small>Demo mode does not upload or pretend to encrypt files.</small>':''}</div>`:''}`}
function propertyGrowthFromMarket(id){const p=Market.catalog.find(p=>p.id===id)||Market.inventory.find(p=>p.id===id);Growth.price=p.purpose==='Sale'?p.price:5000000;Growth.label=p.purpose==='Sale'?'Unverified seller asking price; edit your purchase assumption.':'Rental price is not a purchase price; enter your own assumption.';go('investment')}
async function publishMarket(id,publish){try{if(Market.demo){const p=marketDemo.properties.find(p=>p.id===id);if(publish&&p.status!=='Available')throw Error('Mark property Available before publication');p.published=publish;saveMarketDemo();Market.catalog=localCatalog()}else{const p=Market.inventory.find(p=>p.id===id);await marketCall('POST','/api/market/properties/'+id+'/'+(publish?'publish':'unpublish'),{version:p.version,authorizedToAdvertise:publish});await refreshMarket(false)}render();toast(publish?'Listing published':'Listing withdrawn')}catch(e){toast(e.message)}}
async function submitMarketEnquiry(e,id){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.contactConsent=$('enquiryConsent').checked;let result;if(Market.demo){let r=marketDemo.requests.find(r=>r.propertyId===id);if(!r){r={id:uid('demoReq'),propertyId:id,propertyTitle:marketDemo.properties.find(p=>p.id===id).title,buyerName:'Ananya • Demo Buyer',status:'Pending',version:1,messages:[],documents:[],created:new Date().toISOString(),demoPhone:d.phone};marketDemo.requests.unshift(r)}r.messages.push({id:uid('m'),sender_id:'demoBuyer',body:d.message,created:new Date().toISOString()});saveMarketDemo();Market.requests=marketDemo.requests;result={id:r.id}}else result=await marketCall('POST','/api/market/properties/'+id+'/enquire',d);go('marketThread',{id:result.id});toast('Enquiry submitted')}catch(e){toast(e.message)}finally{b.disabled=false}}
async function requestsMarket(){const session=Firm.token;if(marketLive())await refreshMarket(false);if(route!=='marketRequests'||session!==Firm.token)return;$('app').innerHTML=`${sessionBanner()}<div class="eyebrow">CONVERSATIONS, CONTACT & VISITS</div><h1>${buyerSide()?'My enquiries':'Buyer enquiries'}</h1><div class="panel">${Market.requests.map(r=>`<div class="listrow" onclick="go('marketThread',{id:'${r.id}'})"><div class="row"><strong>${esc(buyerSide()?r.propertyTitle:r.buyerName)}</strong><span class="tag">${esc(r.status)}</span></div><small>${esc(r.propertyTitle)}</small><small>${new Date(r.created).toLocaleDateString('en-IN')} · ${r.messages.length} messages</small></div>`).join('')||'<p class="muted">No enquiries yet.</p>'}</div>`}
async function threadMarket(){const session=Firm.token,requestId=args.id;let r=Market.requests.find(r=>r.id===args.id);if(!Market.demo){try{r=(await marketCall('GET','/api/market/requests/'+args.id)).request}catch(e){$('app').innerHTML=empty('Enquiry unavailable',esc(e.message));return}}if(!r){$('app').innerHTML=empty('No conversation','Go back to your enquiries.');return}if(route!=='marketThread'||args.id!==requestId||session!==Firm.token)return;Market.thread=r;$('app').innerHTML=`${backbtn()}${sessionBanner()}<div class="row"><h2>${esc(r.propertyTitle)}</h2><span class="tag">${esc(r.status)}</span></div><p class="mini muted">${buyerSide()?'Your conversation with the seller.':'Buyer: '+esc(r.buyerName)}</p>${r.status==='Accepted'?`<div class="contactcard"><strong>Contact released by consent</strong><small>Phone is user-supplied, not identity-verified.</small>${(buyerSide()?r.sellerPhone:r.buyerPhone)&&/^\d{10}$/.test(buyerSide()?r.sellerPhone:r.buyerPhone)?`<a class="btn outline" href="tel:+91${buyerSide()?r.sellerPhone:r.buyerPhone}">Call ${buyerSide()?'seller':'buyer'}</a>`:'<small>No real contact supplied in this record.</small>'}</div>`:'<div class="notice blue">Contact details stay hidden until the seller accepts this enquiry.</div>'}<div class="conversation">${r.messages.map(m=>`<div class="bubble ${m.sender_id===Market.user.id?'mine':''}"><small>${m.sender_id===Market.user.id?'You':buyerSide()?'Seller':'Buyer'}</small><p>${esc(m.body)}</p><small>${new Date(m.created).toLocaleString('en-IN')}</small></div>`).join('')}</div>${['Pending','Accepted'].includes(r.status)?`<form class="panel" onsubmit="sendMarketMessage(event,'${r.id}')"><label>Message to ${buyerSide()?'seller':'buyer'}</label><textarea name="message" required maxlength="2000"></textarea><div class="space"></div><button class="btn full">Send message</button></form>`:''}${!buyerSide()&&r.status==='Pending'&&sellerAdmin()?`<div class="row"><button class="btn grow" onclick="requestDecision('${r.id}','accept')">Accept enquiry</button><button class="btn outline grow" onclick="requestDecision('${r.id}','decline')">Decline</button></div>`:''}${r.status==='Accepted'?visitPanel(r)+documentPanel(r):''}<p class="footertext">Messages are shared with this enquiry's participants. Internal CRM notes are separate. Closing an enquiry stops future conversation and document access; it cannot recall details or files already received.</p>`}
async function sendMarketMessage(e,id){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{if(Market.demo){const r=marketDemo.requests.find(r=>r.id===id);r.messages.push({id:uid('m'),sender_id:Market.user.id,body:e.target.message.value,created:new Date().toISOString()});saveMarketDemo()}else await marketCall('POST','/api/market/requests/'+id+'/message',{message:e.target.message.value});threadMarket()}catch(e){toast(e.message)}finally{b.disabled=false}}
async function requestDecision(id,action){try{if(Market.demo){let r=marketDemo.requests.find(r=>r.id===id);r.status=action==='accept'?'Accepted':'Declined';r.version++;r.buyerPhone='';r.sellerPhone='';saveMarketDemo()}else await marketCall('POST','/api/market/requests/'+id+'/'+action,{version:Market.thread.version});await refreshMarket(false);threadMarket()}catch(e){toast(e.message)}}
function visitPanel(r){return `<div class="panel"><h2>Site visit</h2>${r.visit?`<strong>${new Date(r.visit.scheduled).toLocaleString('en-IN')}</strong><p><span class="tag">${esc(r.visit.status)}</span> ${r.buyerConfirmedVisit?'<span class="tag">Buyer confirmed in app</span>':''}</p>${buyerSide()&&r.visit.status==='Proposed'?`<button class="btn full" onclick="confirmMarketVisit('${r.id}')">Confirm this proposal</button>`:''}`:'<p class="muted">No visit proposed yet.</p>'}${!buyerSide()?`<form onsubmit="proposeMarketVisit(event,'${r.id}')"><label>Propose a future time</label><input name="scheduled" type="datetime-local" required><label>Public meeting notes</label><input name="note" maxlength="1000"><div class="space"></div><button class="btn secondary full">Send visit proposal</button></form>`:''}</div>`}
async function proposeMarketVisit(e,id){e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.scheduled=new Date(d.scheduled).toISOString();if(Market.demo){let r=marketDemo.requests.find(r=>r.id===id);r.visit={id:uid('v'),scheduled:d.scheduled,status:'Proposed',version:1};r.buyerConfirmedVisit=false;saveMarketDemo()}else await marketCall('POST','/api/market/requests/'+id+'/propose-visit',d);threadMarket()}catch(e){toast(e.message)}}
async function confirmMarketVisit(id){try{if(Market.demo){const r=marketDemo.requests.find(r=>r.id===id);r.visit.status='Confirmed';r.visit.version++;r.buyerConfirmedVisit=true;saveMarketDemo()}else await marketCall('POST','/api/market/requests/'+id+'/confirm-visit',{visitVersion:Market.thread.visit.version});threadMarket()}catch(e){toast(e.message)}}
function documentPanel(r){return `<div class="panel"><h2>Controlled document access</h2><p class="mini muted">Sharing applies to this buyer only. Grants expire after 24 hours. Revoking access cannot remove copies already downloaded.</p>${r.documents.map(d=>`<div class="listrow"><div class="row"><strong>${esc(d.label)}</strong><span class="tag ${d.accessGranted?'':'gray'}">${d.accessGranted?'Access granted':'Restricted'}</span></div>${buyerSide()?d.accessGranted?`<button class="btn outline" onclick="downloadDocument('${d.id}',this)">Create secure download link</button>`:'<small>Ask the seller to release this record.</small>':sellerAdmin()?`<form onsubmit="grantDocument(event,'${r.id}','${d.id}',${d.accessGranted?'true':'false'})">${input('Confirm account password','password','','password',true)}${input('Authenticator / recovery code, if enabled','otp')}<div class="space"></div><button class="btn ${d.accessGranted?'outline':'secondary'}">${d.accessGranted?'Revoke future access':'Grant this buyer 24-hour access'}</button></form>`:''}</div>`).join('')||'<p class="muted">No source documents uploaded. Request specific documents in the conversation.</p>'}</div>`}
async function uploadPrivateDocument(e,id){e.preventDefault();if(Market.demo)return;const f=e.target.documentFile.files[0];if(!f||f.size>512000){toast('Choose a PDF/JPEG/PNG below 500 KiB');return}const b=e.target.querySelector('button');b.disabled=true;try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f)});await marketCall('POST','/api/market/properties/'+id+'/documents',{filename:f.name,mime:f.type,label:e.target.elements.namedItem('label').value,data:base64});toast('Document encrypted and stored privately')}catch(e){toast(e.message)}finally{b.disabled=false}}
async function grantDocument(e,rid,did,revoke){e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await marketCall('POST','/api/market/requests/'+rid+'/grant-document',{...d,documentId:did,revoke});threadMarket()}catch(e){toast(e.message)}}
async function downloadDocument(id,b){try{const r=await marketCall('POST','/api/market/documents/'+id+'/ticket');b.outerHTML=`<a class="btn" href="${esc(Firm.endpoint+r.path)}" rel="noreferrer">Open one-time download (60 seconds)</a>`}catch(e){toast(e.message)}}

const extraLabels={projectName:'Project name',builder:'Builder / developer',constructionStatus:'Construction / possession stage',possessionDate:'Seller-stated possession date',areaBasis:'Area basis',carpetArea:'Carpet area (sq ft)',builtUpArea:'Built-up area (sq ft)',superArea:'Super built-up area (sq ft)',baths:'Bathrooms',balconies:'Balconies',floor:'Floor number',totalFloors:'Total floors',age:'Building age (years)',parking:'Parking spaces claimed',lifts:'Lifts claimed',maintenance:'Monthly maintenance (INR)',uds:'Undivided land share (sq yd)',rera:'RERA reference',oc:'Occupancy certificate availability',cc:'Completion certificate availability',lengthM:'Plot length (m)',widthM:'Plot width (m)',roadStatus:'Road formation / current condition',water:'Water supply statement',power:'Power / backup statement',drainage:'Drainage statement',landUse:'Seller-stated land use',boundary:'Boundary / survey status',expectedRent:'Seller-quoted monthly rent (INR)'};
const numericExtras=new Set(['carpetArea','builtUpArea','superArea','baths','balconies','floor','totalFloors','age','parking','lifts','maintenance','uds','lengthM','widthM','expectedRent']);
function sellerEditor(){if(!sellerWrite()){$('app').innerHTML=empty('Read-only role','Ask a manager for editing access.');return}const p=Market.inventory.find(p=>p.id===args.id)||{},x=p.insights||{};Market.edit=JSON.parse(JSON.stringify(p));photoDraft=p.photo||'';$('app').innerHTML=`${backbtn()}<div class="eyebrow">SELLER LISTING STUDIO</div><h1>${p.id?'Refine your listing.':'Tell the property story.'}</h1><div class="notice blue">This saves private firm inventory. Publication is a separate owner/manager action. Editing a published property hides its older public version until republished.</div><form id="sellerStudio" onsubmit="saveSellerStudio(event)"><div class="panel"><div class="stepbadge">01 · CORE PROPERTY FACTS</div>${input('Listing title','title',p.title,'text',true)}<div class="grid">${select('Type','type',['Plot','Apartment','House','Commercial','Farm land'],p.type||'Plot')}${select('Purpose','purpose',['Sale','Rent'],p.purpose||'Sale')}${input('Asking price (INR)','price',p.price,'number',true,'min="1" step="0.01"')}${input('Listed area','area',p.area?Number(p.area).toFixed(2):'','number',true,'min="0.01" step="0.01"')}${select('Area unit','unit',['sq yd','sq ft','sq m','acre'],p.unit||'sq yd')}${select('Availability','status',['Draft','Available','On hold','Sold','Rented'],p.status||'Draft')}${input('Bedrooms (where applicable)','bhk',p.bhk,'number',false,'min="0"')}${select('Facing','facing',['Not supplied','East','West','North','South','North East','North West','South East','South West'],p.facing||'Not supplied')}</div></div><div class="panel"><div class="stepbadge">02 · LOCATION & IDENTIFIERS</div><div class="grid">${input('City','city',p.city||'Amaravati','text',true)}${input('District','district',p.district,'text',true)}${input('Mandal','mandal',p.mandal)}${input('Village / locality','village',p.village,'text',true)}${input('Latitude','lat',p.lat,'number',false,'step="any"')}${input('Longitude','lon',p.lon,'number',false,'step="any"')}</div>${input('Survey number','survey',p.survey)}${input('CRDA plot code','plotCode',p.plotCode)}${input('Approval reference (seller supplied)','approval',p.approval)}${input('Road width (m)','road',p.road,'number',false,'min="0" step="0.1"')}</div><details open><summary>03 · In-depth plot or flat facts</summary><p class="mini muted">Supply only what you know. Missing values remain Not supplied, rather than being guessed.</p><div class="grid">${Object.entries(extraLabels).map(([k,l])=>input(l,'x_'+k,x[k],numericExtras.has(k)?'number':k==='possessionDate'?'date':'text',false,numericExtras.has(k)?'min="0" step="any"':'')).join('')}</div><label>Amenities (comma separated; seller claims)</label><input name="amenities" value="${esc((x.amenities||[]).join(', '))}" maxlength="1000"></details><div class="panel"><div class="stepbadge">04 · DESCRIPTION, MEDIA & CONTACT</div><label>Description</label><textarea name="description" maxlength="2500">${esc(p.description||'')}</textarea><label>Property photo</label><input type="file" accept="image/*" onchange="readPhoto(this)"><div id="photopreview">${photoDraft?`<img class="photo-preview" src="${photoDraft}" alt="Selected property photo">`:''}</div>${input('Public seller / business display name','seller',p.seller||Market.user.name)}${input('Contact mobile (released after enquiry acceptance)','phone',p.phone,'tel',false,'pattern="[6-9][0-9]{9}" maxlength="10"')}<small>Contact is buyer-enquiry scoped. Do not put personal IDs, private owner numbers or confidential documents into public descriptions.</small></div><button class="btn full">Save private property inventory</button></form>`}
async function saveSellerStudio(e){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=Object.fromEntries(new FormData(e.target)),p={};for(const k of ['title','type','purpose','unit','status','facing','city','district','mandal','village','survey','plotCode','approval','description','seller','phone'])p[k]=f[k];for(const k of ['price','area','bhk','lat','lon','road'])p[k]=f[k]===''?null:num(f[k]);p.insights={};for(const k of Object.keys(extraLabels)){const v=f['x_'+k];if(v!==''&&v!==undefined)p.insights[k]=numericExtras.has(k)?+v:v}p.insights.amenities=(f.amenities||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,20);if(photoDraft)p.photo=photoDraft;p.assignedTo=Market.edit.assignedTo||Market.user.id;p.branchId=Market.edit.branchId||null;let id=Market.edit.id;if(id)p.version=Market.edit.version;if(Market.demo){if(id){const old=marketDemo.properties.find(x=>x.id===id);Object.assign(old,p,{version:old.version+1,published:false})}else{id=uid('dp');marketDemo.properties.unshift({...p,id,version:1,published:false,demo:true,views:0})}saveMarketDemo();Market.inventory=marketDemo.properties;Market.catalog=localCatalog()}else{const result=await marketCall(id?'PATCH':'POST',id?'/api/properties/'+id:'/api/properties',p);id=result.id;await refreshMarket(false)}go('marketProperty',{id});toast('Private inventory saved; review before publishing')}catch(e){toast(e.message)}finally{b.disabled=false}}

function dossierPage(){const p=Market.catalog.find(p=>p.id===args.id)||Market.inventory.find(p=>p.id===args.id);if(!p){$('app').innerHTML=empty('Select a property','Open a property to see its detailed insights.');return}const x=p.insights||{},flat=p.type==='Apartment',sample=window.DILIGENCE_SAMPLES[flat?'Apartment':'Plot'],required=flat?['projectName','builder','carpetArea','areaBasis','rera','oc','cc','uds','maintenance','parking']:['lengthM','widthM','roadStatus','landUse','water','power','drainage','boundary'],known=required.filter(k=>x[k]!==undefined&&x[k]!==''),missing=required.filter(k=>x[k]===undefined||x[k]==='');$('app').innerHTML=`${backbtn()}<div class="dossierhero"><div class="eyebrow">PROPERTY INSIGHT DOSSIER</div><h1>${flat?'Understand the flat.':'Understand the parcel.'}</h1><p>${esc(p.title)}</p><span class="tag amber">${Market.demo?'SYNTHETIC EVIDENCE EXAMPLE':'SELLER FIELDS + RECORDS NOT YET CONNECTED'}</span></div><div class="panel"><div class="row"><h2>Information completeness</h2><strong>${known.length}/${required.length}</strong></div><div class="legalprogress"><span style="width:${known.length/required.length*100}%"></span></div><p class="mini muted">Counts supplied fields only. This is not a safety, legal, investment or title-quality score.</p><div class="facts">${required.map(k=>fact(extraLabels[k],x[k])).join('')}</div></div><div class="panel"><h2>Practical checks to resolve</h2><ul class="insightlist">${missing.map(k=>`<li>${esc(extraLabels[k])}: not supplied.</li>`).join('')||'<li>Core selected fields are filled; source documents and independent checks are still required.</li>'}${flat?'<li>Compare carpet, built-up and super built-up area on the same unit basis; confirm the agreement and approved plan.</li><li>Check the actual unit, linked land share, parking rights and possession/occupancy records where applicable.</li>':'<li>Compare survey/plot identity, extent and boundaries across the deed, revenue records, planning records and a physical survey.</li><li>Check road access, permitted land use, utilities and current site condition independently.</li>'}</ul></div>${flat&&x.carpetArea&&p.price?`<div class="panel"><h2>Price basis</h2><div class="facts">${fact('Asking price per listed unit',money(p.price/p.area)+' / '+p.unit)}${fact('Asking price per carpet sq ft',money(p.price/x.carpetArea)+' / sq ft')}${fact('Seller-quoted maintenance',x.maintenance?money(x.maintenance)+' / month':null)}${fact('Seller-quoted rent',x.expectedRent?money(x.expectedRent)+' / month':null)}</div><small>Seller inputs, not independent market comparables or guaranteed rental income.</small></div>`:''}<div class="panel"><h2>Evidence-linked record review</h2><p class="mini muted">The structure takes inspiration from evidence-led property diligence. A plot code alone does not establish ownership, charges or a clear title.</p>${Market.demo?`<div class="notice">${esc(sample.notice)} No real Landeed API, government search, court search or legal verification was performed.</div>${sample.sections.map(s=>`<details><summary>${esc(s.title)} <span class="tag gray">${esc(s.status)}</span></summary><p>${esc(s.summary)}</p>${s.findings.map(f=>`<div class="sourcefinding"><strong>${esc(f.text)}</strong><small>Source: ${esc(f.source_id||'Not supplied')} ${f.page?'· sample page '+f.page:''} · synthetic</small></div>`).join('')}</details>`).join('')}<h3>Sample coverage gaps</h3><p class="mini">EC example covers only the stated period. Litigation, CERSAI and physical survey are Not searched / Not done. Missing evidence must not become a green clearance badge.</p>`:`<div class="notice blue">No live document-procurement or title-report provider is connected. Ownership chain, EC, mortgage releases, litigation, statutory approvals and underlying source pages remain Not retrieved / Not verified.</div><p class="mini">Seller-uploaded files can be requested in your enquiry. A file being available does not establish its authenticity or legal sufficiency.</p>`}</div><div class="row"><button class="btn grow" onclick="go('plotAI')">Nearby & CRDA research</button><button class="btn secondary grow" onclick="propertyGrowthFromMarket('${p.id}')">Investment scenarios</button></div>`}
function accountMarket(){$('app').innerHTML=`${sessionBanner()}<div class="accounthead"><div class="bigavatar">${esc(Market.user.name.slice(0,1))}</div><h1>${esc(Market.user.name)}</h1><p>${esc(Market.user.email||'')}</p><span class="tag">${buyerSide()?'BUYER':esc(Market.user.role.toUpperCase())}</span></div><div class="panel linklist"><a href="#" onclick="event.preventDefault();go('marketSecurity')">Account security & sessions →</a><a href="#" onclick="event.preventDefault();go('plotAI')">Plot and nearby research →</a><a href="#" onclick="event.preventDefault();go('investment')">10-year investment scenarios →</a>${!buyerSide()?'<a href="#" onclick="event.preventDefault();go(\'firmMore\')">Firm team, branches & CRM →</a>':''}<a href="#" onclick="event.preventDefault();go('firmSettings')">Backend connection →</a><a href="#" onclick="event.preventDefault();go('about')">Data-source information →</a></div>${buyerSide()?`<form class="panel" onsubmit="saveBuyerPreferences(event)"><h2>My search preferences</h2>${input('Preferred city','city',Market.profile.city)}${select('Preferred type','type',['','Plot','Apartment','House','Commercial','Farm land'],Market.profile.type||'')}${input('Budget ceiling (INR)','maxPrice',Market.profile.maxPrice,'number',false,'min="0"')}<div class="space"></div><button class="btn secondary full">Save preferences</button></form>`:''}<button class="btn danger full" onclick="marketLogout()">${Market.demo?'Exit demo':'Sign out & clear current session'}</button><p class="footertext">Account authentication is not identity proofing or property-ownership verification. Real provider integrations and independent review are still required.</p>`}
async function saveBuyerPreferences(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{if(Market.demo){marketDemo.profile=d;Market.profile=d;saveMarketDemo()}else{await marketCall('POST','/api/buyer/preferences',d);Market.profile=d}toast('Search preferences saved')}catch(e){toast(e.message)}}
async function securityMarket(){const session=Firm.token;if(Market.demo){$('app').innerHTML=`${backbtn()}<div class="eyebrow">ACCOUNT PROTECTION</div><h1>Security controls</h1><div class="notice">Offline demo: no real passwords, authenticator factors or document encryption keys are created here.</div><div class="panel"><h2>Available in connected mode</h2><ul class="insightlist"><li>Server-side account and firm isolation.</li><li>Optional authenticator-based MFA and single-use recovery codes.</li><li>Active-session list and session revocation.</li><li>Encrypted private documents with expiring buyer grants.</li><li>One-use downloads that recheck grants and sessions.</li></ul><p class="mini muted">No software build is a complete-security guarantee. Production email/phone verification, malware scanning, security review and device testing are not certified by this demo.</p></div>`;return}try{const [s,list]=await Promise.all([marketCall('GET','/api/security/status'),marketCall('GET','/api/security/sessions')]);if(route!=='marketSecurity'||session!==Firm.token)return;Market.security=s;$('app').innerHTML=`${backbtn()}<div class="eyebrow">YOUR ACCOUNT, YOUR CONTROL</div><h1>Security centre</h1><div class="panel"><div class="row"><h2>Authenticator protection</h2><span class="tag">${s.mfaEnabled?'Enabled':'Not enabled'}</span></div><p class="mini muted">Time-based authenticator codes, with recovery codes kept offline. This is not a property verification badge.</p>${s.mfaEnabled?`<small>${s.recoveryRemaining} recovery codes remain.</small><form onsubmit="disableMarketMfa(event)">${input('Current password','password','','password',true)}${input('Authenticator / recovery code','otp','','text',true)}<div class="space"></div><button class="btn outline full">Disable authenticator protection</button></form>`:s.encryptionConfigured?`<form onsubmit="setupMarketMfa(event)">${input('Confirm current password','password','','password',true)}<div class="space"></div><button class="btn full">Set up authenticator</button></form>`:'<div class="notice">Server encryption key must be configured before authenticator setup or private document upload can be enabled.</div>'}<div id="mfaSetup"></div></div><div class="panel"><h2>Active sessions</h2>${list.sessions.map(x=>`<div class="listrow"><strong>${x.current?'This session':'Other session'}</strong><small>${esc(x.label)}<br>Expires ${new Date(x.expires*1000).toLocaleString('en-IN')}</small><button class="btn outline" onclick="revokeMarketSession('${x.id}')">Revoke ${x.current?'and sign out':'session'}</button></div>`).join('')}</div><div class="panel"><h2>Change password</h2><form onsubmit="changeMarketPassword(event)">${input('Current password','currentPassword','','password',true)}${input('New passphrase (15+ characters)','newPassword','','password',true,'minlength="15" maxlength="200"')}${input('Authenticator / recovery code, if enabled','otp')}<div class="space"></div><button class="btn secondary full">Change password & revoke all sessions</button></form></div>`}catch(e){toast(e.message)}}
async function setupMarketMfa(e){e.preventDefault();try{const r=await marketCall('POST','/api/security/mfa/setup',{password:e.target.password.value});Market.setup=r;$('mfaSetup').innerHTML=`<div class="notice blue">Add a manual account in your authenticator app: issuer Agent Mart, account ${esc(r.account)}. This secret is shown only for setup and must not be shared.</div><label>Manual setup key</label><textarea readonly>${esc(r.secret)}</textarea><form onsubmit="confirmMarketMfa(event)">${input('Current 6-digit authenticator code','otp','','text',true,'pattern="[0-9]{6}" maxlength="6"')}<div class="space"></div><button class="btn full">Confirm setup</button></form>`}catch(e){toast(e.message)}}
async function confirmMarketMfa(e){e.preventDefault();try{const r=await marketCall('POST','/api/security/mfa/confirm',{otp:e.target.otp.value});Market.setup=null;Market.recovery=r.recoveryCodes;$('mfaSetup').innerHTML=`<div class="notice">Authenticator enabled. Save these recovery codes offline now. They are not saved in app storage and each can be used only once.</div><textarea readonly style="min-height:220px">${esc(r.recoveryCodes.join('\n'))}</textarea><button class="btn secondary full" onclick="Market.recovery=[];securityMarket()">I saved the codes; close this view</button>`}catch(e){toast(e.message)}}
async function disableMarketMfa(e){e.preventDefault();try{await marketCall('POST','/api/security/mfa/disable',Object.fromEntries(new FormData(e.target)));securityMarket();toast('Authenticator disabled; other sessions revoked')}catch(e){toast(e.message)}}
async function revokeMarketSession(id){try{const r=await marketCall('DELETE','/api/security/sessions/'+id);if(r.currentRevoked)await marketLogout();else securityMarket()}catch(e){toast(e.message)}}
async function changeMarketPassword(e){e.preventDefault();try{await marketCall('POST','/api/auth/password',Object.fromEntries(new FormData(e.target)));Firm.token='';await marketLogout();toast('Password changed; sign in again on each device')}catch(e){toast(e.message)}}
route='portal';args={};stack=[];render();

