function translated43(text){if(Language43.code==='en')return text;const clean=text.trim(),star=clean.endsWith(' *')?' *':'',base=star?clean.slice(0,-2):clean,pair=UI43[base];if(pair)return text.replace(clean,pair[Language43.code==='te'?0:1]+star);return text}
function applyLanguage43(){Language43.pending=false;document.documentElement.lang=Language43.code;document.querySelectorAll('select option:not([value])').forEach(o=>o.value=o.textContent);const tree=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=tree.nextNode()){const el=n.parentElement;if(!el||el.closest('script,style,textarea,input,[data-keep-language],.classiccard h3,.card h3,.marketcard h3,.fact b,.sourcefinding,.ainarrative,.conversation .bubble p,.accounthead h1,.accounthead p'))continue;const last=Language43.last.get(n),current=n.nodeValue;if(last!==current)Language43.original.set(n,current);const original=Language43.original.get(n)||current,value=translated43(original);if(n.nodeValue!==value)n.nodeValue=value;Language43.last.set(n,value)}document.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{for(const key of ['placeholder','aria-label']){const val=el.getAttribute(key);if(val===null)continue;const data='original43'+key.replace('-','');if(!el.dataset[data])el.dataset[data]=val;const t=translated43(el.dataset[data]);if(t!==val)el.setAttribute(key,t)}});document.querySelectorAll('.languagebutton43').forEach(b=>{const label={en:'EN',te:'తెలు',hi:'हिं'}[Language43.code];if(b.textContent!==label)b.textContent=label})}
window.applyLanguage43=applyLanguage43;
function scheduleLanguage43(){if(Language43.pending)return;Language43.pending=true;requestAnimationFrame(applyLanguage43)}
new MutationObserver(scheduleLanguage43).observe(document.body,{childList:true,subtree:true,characterData:true});
function chooseLanguage43(){if($('languageSheet43'))return;const box=document.createElement('div');box.id='languageSheet43';box.className='langbackdrop43';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label','Choose language');box.innerHTML=`<section class="langsheet43"><h2>Choose language</h2><p>English · తెలుగు · हिन्दी</p>${[['en','English'],['te','తెలుగు'],['hi','हिन्दी']].map(([k,l])=>`<button data-keep-language class="${Language43.code===k?'selected':''}" onclick="setLanguage43('${k}')"><span>${l}</span><span>${Language43.code===k?'✓':'→'}</span></button>`).join('')}<button class="langclose43" onclick="document.getElementById('languageSheet43').remove()">Close</button></section>`;box.addEventListener('click',e=>{if(e.target===box)box.remove()});document.body.appendChild(box);box.querySelector('button').focus();applyLanguage43()}
function setLanguage43(code){if(!['en','te','hi'].includes(code))return;Language43.code=code;localStorage.setItem('agentmart_language43',code);$('languageSheet43')?.remove();applyLanguage43()}
toggleLang=chooseLanguage43;
