function renderPlatformBanner45(){document.querySelectorAll('.platformBanner45').forEach(e=>e.remove());if(!['home','sellerHome','roleEntry'].includes(route)||!PlatformClient45.config)return;const side=Market.user?(buyerSide()?'buyer':'seller'):'all';const notices=PlatformClient45.config.announcements.filter(a=>a.audience==='all'||a.audience===side);if(notices.length)$('app').insertAdjacentHTML('afterbegin',notices.map(a=>`<div class="notice blue platformBanner45"><strong>${esc(a.title)}</strong><p>${esc(a.body)}</p></div>`).join(''))}
