async function submitReport45(e,id){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{if(Market.demo){$('reportReceipt45').textContent='Fictional demo report recorded on this screen. No platform case was created.';return}const r=await marketCall('POST','/api/reports',{...Object.fromEntries(new FormData(e.target)),propertyId:id});$('reportReceipt45').textContent='Report received. Reference: '+r.id;toast('Report submitted to platform moderation')}catch(e){toast(e.message)}finally{b.disabled=false}}
const crdaBefore45=crda;crda=function(){crdaBefore45();$('app').insertAdjacentHTML('beforeend',`<div class="panel"><h2>Platform-curated parcel references</h2><p class="mini muted">Import references reviewed by the platform team. These are not sale listings or ownership verification.</p><button class="btn outline full" onclick="loadPlatformParcels45(this)">Load platform references (first 100)</button></div>`)};
async function loadPlatformParcels45(b){if(Market.demo||!Firm.endpoint){toast('Connect your backend to load platform references.');return}b.disabled=true;try{const r=await firmCall('GET','/api/platform/public-parcels?limit=100&offset=0');let count=0;for(const f of r.features){try{const p=normalize(f,'Platform-curated reference');const index=state.refs.findIndex(x=>x.code===p.code);if(index>=0)state.refs[index]=p;else state.refs.push(p);count++}catch(e){}}persist();toast(count+' platform references loaded; '+r.total+' available on the server.');crda()}catch(e){toast(e.message)}finally{b.disabled=false}}
setInterval(()=>{if(!document.hidden&&['home','sellerHome','roleEntry'].includes(route)&&!Market.demo)loadPlatformConfig45()},60000);
const aboutBefore45=aboutPage;aboutPage=function(){aboutBefore45();const label=$('app').querySelector('.eyebrow');if(label)label.textContent='AGENT MART • 4.5';$('app').insertAdjacentHTML('beforeend','<div class="panel"><h2>Platform administration</h2><p>Platform listing moderation, account access controls, announcements and buyer reporting use the updated backend. Demo mode is fictional.</p></div>')};
